import json,sys,types
SOURCES={'input_layout': '"""Preserve the line grammar used by line-oriented accepted submissions."""\n\n\ndef layout(pid,text):\n    words = text.split()\n    fixed = {"106A":(1,2),"724A":(1,1),"777A":(1,1),"114A":(1,1),\n             "479A":(1,1,1),"75A":(1,1),"604A":(5,5,2)}\n    if pid in fixed:\n        sizes = fixed[pid]\n    elif pid in ("139A","626A","272A","389A","831A","847M","849A","864B","888B"):\n        sizes = (1,len(words)-1)\n    elif pid in ("450A","680B","371A","385A","435A","862A"):\n        sizes = (2,len(words)-2)\n    elif pid=="368A":\n        sizes = (2,len(words)-3,1)\n    elif pid=="779A":\n        n = int(words[0])\n        sizes = (1,n,n)\n    else:\n        return text\n    if sum(sizes)!=len(words) or any(x<1 for x in sizes):\n        raise ValueError("input line grammar mismatch")\n    lines,offset = [],0\n    for size in sizes:\n        lines.append(" ".join(words[offset:offset+size]))\n        offset += size\n    return "\\n".join(lines)+"\\n"\n', 'recipes': '"""Authored deterministic tests, strict input checks and integer/token oracles."""\nfrom collections import Counter, deque\nimport itertools\nimport math\nimport random\nimport re\nfrom input_layout import layout\n\nIDS = ("139A", "108A", "742A", "626A", "450A", "979A", "114A", "680B",\n       "622A", "777A", "479A", "75A", "131A", "17A", "515A", "577A",\n       "58A", "1036A", "124A", "476A", "859B", "659A")\n\nRULES = {\n    "139A": "n=1..1000; seven capacities in0..1000 with positive sum; simulate cyclic reading; unique finishing weekday.",\n    "108A": "Exactly HH:MM,00<=HH<=23,00<=MM<=59; search strictly later, wrapping at midnight; unique nearest palindrome.",\n    "742A": "n=0..10^9; exact modular exponentiation1378^n mod10; unique digit.",\n    "626A": "n=1..200 and exactly n U/R/D/L letters; count equal pairs of prefix coordinates; unique integer.",\n    "450A": "n,m=1..100; exactly n needs in1..100; queue simulation with m-candy rounds; unique last child, including ties.",\n    "979A": "n=0..10^18; n+1 congruent radial sectors; zero cuts for one sector, diameters halve even sector counts; otherwise one cut per boundary.",\n    "114A": "k,l=2..2^31-1; only l=k^e,e>=1 yields YES and importance e-1; otherwise NO; integer powers only.",\n    "680B": "1<=a<=n<=100; exactly n bits; at each distance catch criminals only if every city at that distance has one.",\n    "622A": "n=1..10^14; exact integer triangular-block search; unique offset within1..block; no floating arithmetic.",\n    "777A": "n=1..2*10^9,x=0..2; six swaps form identity; invert the remaining swaps in reverse chronological order.",\n    "479A": "Three integers in1..10; enumerate ordered binary expression trees using+/*; unique maximum, no reordering.",\n    "75A": "Two positive integers in1..10^9; remove zero digits from both operands and their sum, then test equality.",\n    "131A": "1..100 ASCII Latin letters; invert all cases iff every character after the first is uppercase, including one-letter inputs.",\n    "17A": "n=2..1000,k=0..1000; sieve primes and count primes equal to neighboring prime sums plus1; threshold predicate.",\n    "515A": "a,b=-10^9..10^9,s=1..2*10^9; Manhattan distance <=s and even remaining steps; YES/NO is case-insensitive.",\n    "577A": "n=1..10^5,x=1..10^9; enumerate first coordinate divisors with second coordinate <=n; unique count.",\n    "58A": "1..100 lowercase ASCII letters; greedy subsequence hello; unique YES/NO.",\n    "1036A": "n,k=1..10^18; n independent integer-height triangles each of base2 contribute their height as area; answer ceil(k/n).",\n    "124A": "0<=a,b<n<=100; enumerate positions with at least a predecessors and at most b successors; unique count.",\n    "476A": "n=1..10000,m=2..10; enumerate feasible move counts ceil(n/2)..n and minimize those divisible by m; -1 if none.",\n    "859B": "N=1..10^6; search integer bounding rectangle sides with area>=N; min2*(width+height). Removing final excess corner cells realizes areaN without increasing perimeter.",\n    "659A": "n=1..100,a=1..n,b=-100..100; step around cyclic entrances in signed direction; unique entrance.",\n}\n\n\ndef integers(text, count=None):\n    tokens = text.split()\n    if not tokens or any(not re.fullmatch(r"-?\\d+", t) for t in tokens):\n        raise ValueError("noninteger input")\n    values = list(map(int, tokens))\n    if count is not None and len(values) != count:\n        raise ValueError("wrong integer count")\n    return values\n\n\ndef within(value, low, high):\n    if not low <= value <= high:\n        raise ValueError(f"integer outside [{low},{high}]: {value}")\n\n\ndef output(pid, text):\n    if pid in ("108A", "131A", "58A"):\n        words = text.split()\n        if len(words) != 1:\n            raise ValueError("expected one word")\n        word = words[0]\n        if pid == "108A":\n            if not re.fullmatch(r"\\d{2}:\\d{2}", word):\n                raise ValueError("invalid time format")\n            hour, minute = map(int, word.split(":"))\n            within(hour, 0, 23)\n            within(minute, 0, 59)\n            now = hour * 60 + minute\n            for step in range(1, 1441):\n                t = (now + step) % 1440\n                candidate = f"{t//60:02}:{t%60:02}"\n                if candidate == candidate[::-1]:\n                    return candidate + "\\n"\n        if not re.fullmatch(r"[A-Za-z]{1,100}" if pid == "131A" else r"[a-z]{1,100}", word):\n            raise ValueError("invalid word")\n        if pid == "131A":\n            return (word.swapcase() if all(c.isupper() for c in word[1:]) else word) + "\\n"\n        cursor = 0\n        for c in word:\n            if cursor < 5 and c == "hello"[cursor]:\n                cursor += 1\n        return ("YES" if cursor == 5 else "NO") + "\\n"\n    if pid == "626A":\n        words = text.split()\n        if len(words) != 2 or not words[0].isdigit():\n            raise ValueError("invalid robot input")\n        n, commands = int(words[0]), words[1]\n        within(n, 1, 200)\n        if len(commands) != n or set(commands) - set("URDL"):\n            raise ValueError("invalid robot commands")\n        positions = Counter({(0, 0): 1})\n        x = y = answer = 0\n        for c in commands:\n            dx, dy = {"U": (0, 1), "R": (1, 0), "D": (0, -1), "L": (-1, 0)}[c]\n            x, y = x + dx, y + dy\n            answer += positions[x, y]\n            positions[x, y] += 1\n        return f"{answer}\\n"\n    v = integers(text)\n    counts = {"139A": 8, "742A": 1, "979A": 1, "114A": 2, "622A": 1,\n              "777A": 2, "479A": 3, "75A": 2, "17A": 2, "515A": 3,\n              "577A": 2, "1036A": 2, "124A": 3, "476A": 2, "859B": 1, "659A": 3}\n    if pid in counts and len(v) != counts[pid]:\n        raise ValueError("wrong integer count")\n    if pid == "139A":\n        n, *days = v\n        within(n, 1, 1000)\n        for d in days:\n            within(d, 0, 1000)\n        if sum(days) == 0:\n            raise ValueError("no reading capacity")\n        i = 0\n        while n > 0:\n            n -= days[i % 7]\n            i += 1\n        answer = (i - 1) % 7 + 1\n    elif pid == "742A":\n        n, = v\n        within(n, 0, 10**9)\n        answer = pow(1378, n, 10)\n    elif pid == "450A":\n        n, m, *needs = v\n        within(n, 1, 100)\n        within(m, 1, 100)\n        if len(needs) != n:\n            raise ValueError("wrong needs count")\n        for a in needs:\n            within(a, 1, 100)\n        queue = deque(enumerate(needs, 1))\n        while queue:\n            answer, remaining = queue.popleft()\n            if remaining > m:\n                queue.append((answer, remaining - m))\n    elif pid == "979A":\n        n, = v\n        within(n, 0, 10**18)\n        answer = 0 if n == 0 else (n + 1) // 2 if n % 2 else n + 1\n    elif pid == "114A":\n        k, l = v\n        within(k, 2, 2**31 - 1)\n        within(l, 2, 2**31 - 1)\n        value, exponent = k, 1\n        while value < l:\n            value *= k\n            exponent += 1\n        return f"YES\\n{exponent-1}\\n" if value == l else "NO\\n"\n    elif pid == "680B":\n        n, a, *bits = v\n        within(n, 1, 100)\n        within(a, 1, n)\n        if len(bits) != n or set(bits) - {0, 1}:\n            raise ValueError("invalid criminal bits")\n        answer = 0\n        for distance in range(n):\n            cities = {a - 1 - distance, a - 1 + distance} & set(range(n))\n            if cities and all(bits[i] for i in cities):\n                answer += len(cities)\n    elif pid == "622A":\n        n, = v\n        within(n, 1, 10**14)\n        left, right = 1, n\n        while left < right:\n            mid = (left + right) // 2\n            if mid * (mid + 1) // 2 >= n:\n                right = mid\n            else:\n                left = mid + 1\n        answer = n - left * (left - 1) // 2\n    elif pid == "777A":\n        n, x = v\n        within(n, 1, 2 * 10**9)\n        within(x, 0, 2)\n        for step in range(n % 6, 0, -1):\n            a, b = (0, 1) if step % 2 else (1, 2)\n            if x in (a, b):\n                x = a + b - x\n        answer = x\n    elif pid == "479A":\n        for x in v:\n            within(x, 1, 10)\n        def expressions(values):\n            if len(values) == 1:\n                return {values[0]}\n            answers = set()\n            for split in range(1, len(values)):\n                for a in expressions(values[:split]):\n                    for b in expressions(values[split:]):\n                        answers.update((a + b, a * b))\n            return answers\n        answer = max(expressions(v))\n    elif pid == "75A":\n        a, b = v\n        within(a, 1, 10**9)\n        within(b, 1, 10**9)\n        def no_zeros(x):\n            return int(str(x).replace("0", ""))\n        return ("YES" if no_zeros(a) + no_zeros(b) == no_zeros(a + b) else "NO") + "\\n"\n    elif pid == "17A":\n        n, k = v\n        within(n, 2, 1000)\n        within(k, 0, 1000)\n        prime = [True] * (n + 1)\n        prime[:2] = [False, False]\n        for p in range(2, math.isqrt(n) + 1):\n            if prime[p]:\n                for multiple in range(p*p, n+1, p):\n                    prime[multiple] = False\n        ps = [p for p in range(2, n+1) if prime[p]]\n        good = sum(a+b+1 <= n and prime[a+b+1] for a, b in zip(ps, ps[1:]))\n        return ("YES" if good >= k else "NO") + "\\n"\n    elif pid == "515A":\n        a, b, s = v\n        within(a, -10**9, 10**9)\n        within(b, -10**9, 10**9)\n        within(s, 1, 2*10**9)\n        distance = abs(a) + abs(b)\n        return ("YES" if s >= distance and (s-distance) % 2 == 0 else "NO") + "\\n"\n    elif pid == "577A":\n        n, x = v\n        within(n, 1, 10**5)\n        within(x, 1, 10**9)\n        answer = sum(x % i == 0 and x//i <= n for i in range(1, min(n, x)+1))\n    elif pid == "1036A":\n        n, k = v\n        within(n, 1, 10**18)\n        within(k, 1, 10**18)\n        answer = (k+n-1)//n\n    elif pid == "124A":\n        n, a, b = v\n        within(n, 1, 100)\n        within(a, 0, n-1)\n        within(b, 0, n-1)\n        answer = sum(p >= a and n-1-p <= b for p in range(n))\n    elif pid == "476A":\n        n, m = v\n        within(n, 1, 10000)\n        within(m, 2, 10)\n        answer = next((moves for moves in range((n+1)//2, n+1) if moves % m == 0), -1)\n    elif pid == "859B":\n        n, = v\n        within(n, 1, 10**6)\n        answer = min(2*(width + (n+width-1)//width) for width in range(1, math.isqrt(n)+2))\n    elif pid == "659A":\n        n, a, b = v\n        within(n, 1, 100)\n        within(a, 1, n)\n        within(b, -100, 100)\n        for _ in range(abs(b)):\n            a += 1 if b > 0 else -1\n            if a == n+1:\n                a = 1\n            if a == 0:\n                a = n\n        answer = a\n    else:\n        raise ValueError("unowned recipe")\n    return f"{answer}\\n"\n\n\ndef extra_inputs(pid):\n    rng = random.Random(int.from_bytes(pid.encode(), "big"))\n    cases = []\n    def add(*values):\n        cases.append(" ".join(map(str, values)) + "\\n")\n    if pid == "139A":\n        for day in range(7):\n            for n in (1, 999, 1000):\n                days = [0]*7\n                days[day] = 1 if n != 999 else 1000\n                add(n, *days)\n        for _ in range(20):\n            add(rng.randint(1,1000), *[rng.randint(0,10) for _ in range(7)])\n        add(1000, *[1000]*7)\n    elif pid == "108A":\n        cases = [f"{h:02}:{m:02}\\n" for h, m in [(0,0),(0,1),(23,59),(23,32),(23,33),(15,51),(5,50),(5,51),(11,11),(12,21),(22,22),(1,9),(1,10)]]\n        cases += [f"{rng.randrange(24):02}:{rng.randrange(60):02}\\n" for _ in range(25)]\n    elif pid == "742A":\n        for n in list(range(20)) + [10**9-i for i in range(8)]:\n            add(n)\n    elif pid == "626A":\n        words = ["U","LR","URDL","UUDDLLRR","UD"*100,"UR"*100,"U"*200,"U"*100+"D"*100,"LR"*99+"UD"]\n        words += ["".join(rng.choice("URDL") for _ in range(n)) for n in (2,3,5,10,50,99,100,199,200)]\n        cases = [f"{len(w)}\\n{w}\\n" for w in words]\n    elif pid == "450A":\n        add(1,1,1)\n        add(1,1,100)\n        add(100,1,*[100]*100)\n        add(100,100,*[1]*100)\n        add(5,3,1,2,3,3,1)\n        add(3,3,7,9,8)\n        add(3,3,10,9,8)\n        for _ in range(20):\n            n,m=rng.randint(1,100),rng.randint(1,100)\n            add(n,m,*[rng.randint(1,100) for _ in range(n)])\n    elif pid == "979A":\n        for n in list(range(25))+[10**18-i for i in range(8)]+[10**9,10**9-1,2**53,2**53+1]:\n            add(n)\n    elif pid == "114A":\n        for k in (2,3,10,31,46340,46341,2**31-1):\n            value=k\n            while value<=2**31-1:\n                add(k,value)\n                if value>2:\n                    add(k,value-1)\n                if value<2**31-1:\n                    add(k,value+1)\n                value*=k\n    elif pid == "680B":\n        add(1,1,0)\n        add(1,1,1)\n        for a in (1,50,51,100):\n            for bits in ([0]*100,[1]*100,[i%2 for i in range(100)]):\n                add(100,a,*bits)\n        for _ in range(25):\n            n=rng.randint(1,100)\n            add(n,rng.randint(1,n),*[rng.randrange(2) for _ in range(n)])\n    elif pid == "622A":\n        for k in (1,2,3,10,1000,10**6,14142135):\n            t=k*(k+1)//2\n            for n in (t-1,t,t+1):\n                if 1<=n<=10**14:\n                    add(n)\n        add(10**14)\n        for _ in range(20):\n            add(rng.randint(1,10**14))\n    elif pid == "777A":\n        for n in list(range(1,13))+list(range(2*10**9-5,2*10**9+1)):\n            for x in range(3):\n                add(n,x)\n    elif pid == "479A":\n        for values in itertools.product((1,2,9,10),repeat=3):\n            add(*values)\n    elif pid == "75A":\n        for a,b in [(1,1),(9,1),(10,10),(101,102),(105,106),(10**9,10**9),(999999999,1),(100000001,999999999),(909090909,909090909)]:\n            add(a,b)\n        for _ in range(25):\n            add(rng.randint(1,10**9),rng.randint(1,10**9))\n    elif pid == "131A":\n        cases=[s+"\\n" for s in ["a","A","z","Z","HTTP","hELLO","Hello","cAPS","aB","AB","Ab","ab","A"*100,"a"+"Z"*99,"z"*100,"Z"*99+"a"]]\n        cases += ["".join(rng.choice("aAzZ") for _ in range(n))+"\\n" for n in (2,3,5,99,100)]\n    elif pid == "17A":\n        for n in (2,3,5,7,13,19,27,100,999,1000):\n            for k in (0,1,2,10,1000):\n                add(n,k)\n    elif pid == "515A":\n        for a,b in [(0,0),(1,0),(-1,1),(10**9,10**9),(-10**9,-10**9),(10**9,0),(1,1),(-2,3)]:\n            distance=abs(a)+abs(b)\n            for s in (max(1,distance-1),max(1,distance),max(1,distance+1),max(1,distance+2),2*10**9):\n                if s<=2*10**9:\n                    add(a,b,s)\n    elif pid == "577A":\n        for n,x in [(1,1),(1,2),(100000,10**9),(100000,1),(100000,999999937),(100000,100000),(100000,999980001),(10,100),(10,99),(10,101)]:\n            add(n,x)\n        for _ in range(20):\n            add(rng.randint(1,10**5),rng.randint(1,10**9))\n    elif pid == "58A":\n        words=["h","hello","hlelo","helllo","helol","hell","hello"+"a"*95,"a"*95+"hello","h"*96+"ello","h"*20+"e"*20+"l"*20+"l"*20+"o"*20,"a"*100,"hellohello"]\n        words += ["".join(rng.choice("heloaz") for _ in range(n)) for n in (3,4,5,6,10,50,99,100)]\n        cases=[w+"\\n" for w in words]\n    elif pid == "1036A":\n        for n,k in [(1,1),(1,10**18),(10**18,1),(10**18,10**18),(999999999999999999,10**18),(2**53,2**53+1),(10**9,10**18),(3,10),(3,9),(3,8)]:\n            add(n,k)\n        for _ in range(20):\n            add(rng.randint(1,10**18),rng.randint(1,10**18))\n    elif pid == "124A":\n        for n in (1,2,3,99,100):\n            for a,b in itertools.product(sorted({0,n//2,n-1}),repeat=2):\n                add(n,a,b)\n    elif pid == "476A":\n        for n in (1,2,3,4,9,10,11,9999,10000):\n            for m in (2,3,9,10):\n                add(n,m)\n    elif pid == "859B":\n        for k in (1,2,3,10,31,999,1000):\n            for n in (k*k-1,k*k,k*k+1,k*(k+1)-1,k*(k+1),k*(k+1)+1):\n                if 1<=n<=10**6:\n                    add(n)\n    elif pid == "659A":\n        for n in (1,2,3,99,100):\n            for a in sorted({1,n//2+1,n}):\n                for b in (-100,-n,-1,0,1,n,100):\n                    add(n,a,b)\n    else:\n        raise ValueError("unowned recipe")\n    return list(dict.fromkeys(cases))\n\n\ndef extras(pid):\n    return [{"input": layout(pid,text),"output":output(pid,text)} for text in extra_inputs(pid)]\n', 'additional': '"""Reviewed unique-answer integer/token tasks; deterministic full-domain generators."""\nfrom collections import Counter\nfrom functools import lru_cache\nimport itertools\nimport json\nimport math\nfrom pathlib import Path\nimport random\nimport re\n\nfrom recipes import integers, within\nfrom input_layout import layout\n\nIDS = tuple("1A 13A 90A 106A 109A 118A 118B 122A 122B 195A 259A 268B 272A 368A 371A 379A 385A 389A 435A 535A 579A 604A 610A 620B 628A 660B 724A 733A 761A 779A 798A 804A 816A 831A 847M 849A 862A 864B 886A 887A 888B 893B 909A 990A 991A".split())\nREVIEW = {\'1008B\': {\'description\': \'There are $$$n$$$ rectangles in a row. You can either turn each rectangle by $$$90$$$ degrees or leave it as it is. If you turn a rectangle, its width will be height, and its height will be width. Notice that you can turn any number of rectangles, you also can turn all or none of them. You can not change the order of the rectangles.\\n\\nFind out if there is a way to make the rectangles go in order of non-ascending height. In other words, after all the turns, a height of every rectangle has to be not greater than the height of the previous rectangle (if it is such).\', \'id\': \'1008/B\', \'input_format\': \'The first line contains a single integer $$$n$$$ ($$$1 \\\\leq n \\\\leq 10^5$$$)\\xa0— the number of rectangles.\\n\\nEach of the next $$$n$$$ lines contains two integers $$$w_i$$$ and $$$h_i$$$ ($$$1 \\\\leq w_i, h_i \\\\leq 10^9$$$)\\xa0— the width and the height of the $$$i$$$-th rectangle.\', \'output_format\': \'Print "YES" (without quotes) if there is a way to make the rectangles go in order of non-ascending height, otherwise print "NO".\\n\\nYou can print each letter in any case (upper or lower).\'}, \'102B\': {\'description\': "Having watched the last Harry Potter film, little Gerald also decided to practice magic. He found in his father\'s magical book a spell that turns any number in the sum of its digits. At the moment Gerald learned that, he came across a number n. How many times can Gerald put a spell on it until the number becomes one-digit?", \'id\': \'102/B\', \'input_format\': "The first line contains the only integer n (0 ≤ n ≤ 10100000). It is guaranteed that n doesn\'t contain any leading zeroes.", \'output_format\': \'Print the number of times a number can be replaced by the sum of its digits until it only contains one digit.\'}, \'106A\': {\'description\': \'There is a card game called "Durak", which means "Fool" in Russian. The game is quite popular in the countries that used to form USSR. The problem does not state all the game\\\'s rules explicitly — you can find them later yourselves if you want.\\n\\nTo play durak you need a pack of 36 cards. Each card has a suit ("S", "H", "D" and "C") and a rank (in the increasing order "6", "7", "8", "9", "T", "J", "Q", "K" and "A"). At the beginning of the game one suit is arbitrarily chosen as trump.\\n\\nThe players move like that: one player puts one or several of his cards on the table and the other one should beat each of them with his cards.\\n\\nA card beats another one if both cards have similar suits and the first card has a higher rank then the second one. Besides, a trump card can beat any non-trump card whatever the cards’ ranks are. In all other cases you can not beat the second card with the first one.\\n\\nYou are given the trump suit and two different cards. Determine whether the first one beats the second one or not.\', \'id\': \'106/A\', \'input_format\': \'The first line contains the tramp suit. It is "S", "H", "D" or "C".\\n\\nThe second line contains the description of the two different cards. Each card is described by one word consisting of two symbols. The first symbol stands for the rank ("6", "7", "8", "9", "T", "J", "Q", "K" and "A"), and the second one stands for the suit ("S", "H", "D" and "C").\', \'output_format\': \'Print "YES" (without the quotes) if the first cards beats the second one. Otherwise, print "NO" (also without the quotes).\'}, \'106B\': {\'description\': "Vasya is choosing a laptop. The shop has n laptops to all tastes.\\n\\nVasya is interested in the following properties: processor speed, ram and hdd. Vasya is a programmer and not a gamer which is why he is not interested in all other properties.\\n\\nIf all three properties of a laptop are strictly less than those properties of some other laptop, then the first laptop is considered outdated by Vasya. Among all laptops Vasya does not consider outdated, he chooses the cheapest one.\\n\\nThere are very many laptops, which is why Vasya decided to write a program that chooses the suitable laptop. However, Vasya doesn\'t have his own laptop yet and he asks you to help him.", \'id\': \'106/B\', \'input_format\': "The first line contains number n (1 ≤ n ≤ 100).\\n\\nThen follow n lines. Each describes a laptop as speed ram hdd cost. Besides,\\n\\n- speed, ram, hdd and cost are integers\\n- 1000\\u2009≤\\u2009speed\\u2009≤\\u20094200 is the processor\'s speed in megahertz\\n- 256\\u2009≤\\u2009ram\\u2009≤\\u20094096 the RAM volume in megabytes\\n- 1\\u2009≤\\u2009hdd\\u2009≤\\u2009500 is the HDD in gigabytes\\n- 100\\u2009≤\\u2009cost\\u2009≤\\u20091000 is price in tugriks\\n\\nAll laptops have different prices.", \'output_format\': \'Print a single number — the number of a laptop Vasya will choose. The laptops are numbered with positive integers from 1 to n in the order in which they are given in the input data.\'}, \'109A\': {\'description\': \'Petya loves lucky numbers. We all know that lucky numbers are the positive integers whose decimal representations contain only the lucky digits 4 and 7. For example, numbers 47, 744, 4 are lucky and 5, 17, 467 are not.\\n\\nPetya wonders eagerly what minimum lucky number has the sum of digits equal to n. Help him cope with the task.\', \'id\': \'109/A\', \'input_format\': \'The single line contains an integer n (1 ≤ n ≤ 106) — the sum of digits of the required lucky number.\', \'output_format\': \'Print on the single line the result — the minimum lucky number, whose sum of digits equals n. If such number does not exist, print -1.\'}, \'118A\': {\'description\': \'Petya started to attend programming lessons. On the first lesson his task was to write a simple program. The program was supposed to do the following: in the given string, consisting if uppercase and lowercase Latin letters, it:\\n\\n- deletes all the vowels,\\n- inserts a character "." before each consonant,\\n- replaces all uppercase consonants with corresponding lowercase ones.\\n\\nVowels are letters "A", "O", "Y", "E", "U", "I", and the rest are consonants. The program\\\'s input is exactly one string, it should return the output as a single string, resulting after the program\\\'s processing the initial string.\\n\\nHelp Petya cope with this easy task.\', \'id\': \'118/A\', \'input_format\': "The first line represents input string of Petya\'s program. This string only consists of uppercase and lowercase Latin letters and its length is from 1 to 100, inclusive.", \'output_format\': \'Print the resulting string. It is guaranteed that this string is not empty.\'}, \'118B\': {\'description\': "Vasya\'s birthday is approaching and Lena decided to sew a patterned handkerchief to him as a present. Lena chose digits from 0 to n as the pattern. The digits will form a rhombus. The largest digit n should be located in the centre. The digits should decrease as they approach the edges. For example, for n = 5 the handkerchief pattern should look like that:\\n\\nYour task is to determine the way the handkerchief will look like by the given n.", \'id\': \'118/B\', \'input_format\': \'The first line contains the single integer n (2 ≤ n ≤ 9).\', \'output_format\': \'Print a picture for the given n. You should strictly observe the number of spaces before the first digit on each line. Every two adjacent digits in the same line should be separated by exactly one space. There should be no spaces after the last digit at the end of each line.\'}, \'122A\': {\'description\': \'Petya loves lucky numbers. Everybody knows that lucky numbers are positive integers whose decimal representation contains only the lucky digits 4 and 7. For example, numbers 47, 744, 4 are lucky and 5, 17, 467 are not.\\n\\nPetya calls a number almost lucky if it could be evenly divided by some lucky number. Help him find out if the given number n is almost lucky.\', \'id\': \'122/A\', \'input_format\': \'The single line contains an integer n (1 ≤ n ≤ 1000) — the number that needs to be checked.\', \'output_format\': \'In the only line print "YES" (without the quotes), if number n is almost lucky. Otherwise, print "NO" (without the quotes).\'}, \'122B\': {\'description\': \'Petya loves lucky numbers. Everybody knows that lucky numbers are positive integers whose decimal representation contains only the lucky digits 4 and 7. For example, numbers 47, 744, 4 are lucky and 5, 17, 467 are not.\\n\\nOne day Petya was delivered a string s, containing only digits. He needs to find a string that\\n\\n- represents a lucky number without leading zeroes,\\n- is not empty,\\n- is contained in s as a substring the maximum number of times.\\n\\nAmong all the strings for which the three conditions given above are fulfilled, Petya only needs the lexicographically minimum one. Find this string for Petya.\', \'id\': \'122/B\', \'input_format\': \'The single line contains a non-empty string s whose length can range from 1 to 50, inclusive. The string only contains digits. The string can contain leading zeroes.\', \'output_format\': \'In the only line print the answer to Petya\\\'s problem. If the sought string does not exist, print "-1" (without quotes).\'}, \'127B\': {\'description\': \'Nicholas, a painter is going to paint several new canvases. Nicholas is sure that the canvases will turn out so great that each one will need framing and being hung on the wall. Frames are what Nicholas decided to begin with.\\n\\nNicholas has n sticks whose lengths equal a1, a2, ... an. Nicholas does not want to break the sticks or glue them together. To make a h × w-sized frame, he needs two sticks whose lengths equal h and two sticks whose lengths equal w. Specifically, to make a square frame (when h = w), he needs four sticks of the same length.\\n\\nNow Nicholas wants to make from the sticks that he has as many frames as possible; to be able to paint as many canvases as possible to fill the frames. Help him in this uneasy task. Note that it is not necessary to use all the sticks Nicholas has.\', \'id\': \'127/B\', \'input_format\': \'The first line contains an integer n (1 ≤ n ≤ 100) — the number of sticks. The second line contains n space-separated integers. The i-th integer equals the length of the i-th stick ai (1 ≤ ai ≤ 100).\', \'output_format\': \'Print the single number — the maximum number of frames Nicholas can make for his future canvases.\'}, \'137B\': {\'description\': \'"Hey, it\\\'s homework time" — thought Polycarpus and of course he started with his favourite subject, IT. Polycarpus managed to solve all tasks but for the last one in 20 minutes. However, as he failed to solve the last task after some considerable time, the boy asked you to help him.\\n\\nThe sequence of n integers is called a permutation if it contains all integers from 1 to n exactly once.\\n\\nYou are given an arbitrary sequence a1, a2, ..., an containing n integers. Each integer is not less than 1 and not greater than 5000. Determine what minimum number of elements Polycarpus needs to change to get a permutation (he should not delete or add numbers). In a single change he can modify any single sequence element (i. e. replace it with another integer).\', \'id\': \'137/B\', \'input_format\': \'The first line of the input data contains an integer n (1 ≤ n ≤ 5000) which represents how many numbers are in the sequence. The second line contains a sequence of integers ai (1 ≤ ai ≤ 5000, 1 ≤ i ≤ n).\', \'output_format\': \'Print the only number — the minimum number of changes needed to get the permutation.\'}, \'13A\': {\'description\': \'Little Petya likes numbers a lot. He found that number 123 in base 16 consists of two digits: the first is 7 and the second is 11. So the sum of digits of 123 in base 16 is equal to 18.\\n\\nNow he wonders what is an average value of sum of digits of the number A written in all bases from 2 to A - 1.\\n\\nNote that all computations should be done in base 10. You should find the result as an irreducible fraction, written in base 10.\', \'id\': \'13/A\', \'input_format\': \'Input contains one integer number A (3 ≤ A ≤ 1000).\', \'output_format\': \'Output should contain required average value in format «X/Y», where X is the numerator and Y is the denominator.\'}, \'143A\': {\'description\': "Vasilisa the Wise from the Kingdom of Far Far Away got a magic box with a secret as a present from her friend Hellawisa the Wise from the Kingdom of A Little Closer. However, Vasilisa the Wise does not know what the box\'s secret is, since she cannot open it again. She hopes that you will help her one more time with that.\\n\\nThe box\'s lock looks as follows: it contains 4 identical deepenings for gems as a 2 × 2 square, and some integer numbers are written at the lock\'s edge near the deepenings. The example of a lock is given on the picture below.\\n\\nThe box is accompanied with 9 gems. Their shapes match the deepenings\' shapes and each gem contains one number from 1 to 9 (each number is written on exactly one gem). The box will only open after it is decorated with gems correctly: that is, each deepening in the lock should be filled with exactly one gem. Also, the sums of numbers in the square\'s rows, columns and two diagonals of the square should match the numbers written at the lock\'s edge. For example, the above lock will open if we fill the deepenings with gems with numbers as is shown on the picture below.\\n\\nNow Vasilisa the Wise wants to define, given the numbers on the box\'s lock, which gems she should put in the deepenings to open the box. Help Vasilisa to solve this challenging task.", \'id\': \'143/A\', \'input_format\': \'The input contains numbers written on the edges of the lock of the box. The first line contains space-separated integers r1 and r2 that define the required sums of numbers in the rows of the square. The second line contains space-separated integers c1 and c2 that define the required sums of numbers in the columns of the square. The third line contains space-separated integers d1 and d2 that define the required sums of numbers on the main and on the side diagonals of the square (1 ≤ r1, r2, c1, c2, d1, d2 ≤ 20). Correspondence between the above 6 variables and places where they are written is shown on the picture below. For more clarifications please look at the second sample test that demonstrates the example given in the problem statement.\', \'output_format\': \'Print the scheme of decorating the box with stones: two lines containing two space-separated integers from 1 to 9. The numbers should be pairwise different. If there is no solution for the given lock, then print the single number "-1" (without the quotes).\\n\\nIf there are several solutions, output any.\'}, \'14B\': {\'description\': \'Among other things, Bob is keen on photography. Especially he likes to take pictures of sportsmen. That was the reason why he placed himself in position x0 of a long straight racetrack and got ready to take pictures. But the problem was that not all the runners passed him. The total amount of sportsmen, training at that racetrack, equals n. And each of them regularly runs distances within a particular segment of the racetrack, which is the same for each sportsman. For example, the first sportsman runs from position a1 to position b1, the second — from a2 to b2\\n\\nWhat is the minimum distance that Bob should move to have a chance to take pictures of each sportsman? Bob can take a picture of a sportsman, if he stands within the segment that this sportsman covers on the racetrack.\', \'id\': \'14/B\', \'input_format\': \'The first line of the input file contains integers n and x0 (1 ≤ n ≤ 100; 0 ≤ x0 ≤ 1000). The following n lines contain pairs of integers ai, bi (0 ≤ ai, bi ≤ 1000; ai ≠ bi).\', \'output_format\': \'Output the required minimum distance in the same units as the positions on the racetrack. If there is no such a position, output -1.\'}, \'165A\': {\'description\': "One day Vasya painted a Cartesian coordinate system on a piece of paper and marked some set of points (x1, y1), (x2, y2), ..., (xn, yn). Let\'s define neighbors for some fixed point from the given set (x, y):\\n\\n- point (x\',\\u2009y\') is (x,\\u2009y)\'s right neighbor, if x\'\\u2009>\\u2009x and y\'\\u2009=\\u2009y\\n- point (x\',\\u2009y\') is (x,\\u2009y)\'s left neighbor, if x\'\\u2009<\\u2009x and y\'\\u2009=\\u2009y\\n- point (x\',\\u2009y\') is (x,\\u2009y)\'s lower neighbor, if x\'\\u2009=\\u2009x and y\'\\u2009<\\u2009y\\n- point (x\',\\u2009y\') is (x,\\u2009y)\'s upper neighbor, if x\'\\u2009=\\u2009x and y\'\\u2009>\\u2009y\\n\\nWe\'ll consider point (x, y) from the given set supercentral, if it has at least one upper, at least one lower, at least one left and at least one right neighbor among this set\'s points.\\n\\nVasya marked quite many points on the paper. Analyzing the picture manually is rather a challenge, so Vasya asked you to help him. Your task is to find the number of supercentral points in the given set.", \'id\': \'165/A\', \'input_format\': \'The first input line contains the only integer n (1 ≤ n ≤ 200) — the number of points in the given set. Next n lines contain the coordinates of the points written as "x y" (without the quotes) (|x|, |y| ≤ 1000), all coordinates are integers. The numbers in the line are separated by exactly one space. It is guaranteed that all points are different.\', \'output_format\': \'Print the only number — the number of supercentral points of the given set.\'}, \'182B\': {\'description\': "Vasya lives in a strange world. The year has n months and the i-th month has ai days. Vasya got a New Year present — the clock that shows not only the time, but also the date.\\n\\nThe clock\'s face can display any number from 1 to d. It is guaranteed that ai ≤ d for all i from 1 to n. The clock does not keep information about the current month, so when a new day comes, it simply increases the current day number by one. The clock cannot display number d + 1, so after day number d it shows day 1 (the current day counter resets). The mechanism of the clock allows you to increase the day number by one manually. When you execute this operation, day d is also followed by day 1.\\n\\nVasya begins each day checking the day number on the clock. If the day number on the clock does not match the actual day number in the current month, then Vasya manually increases it by one. Vasya is persistent and repeats this operation until the day number on the clock matches the actual number of the current day in the current month.\\n\\nA year passed and Vasya wonders how many times he manually increased the day number by one, from the first day of the first month to the last day of the n-th month inclusive, considering that on the first day of the first month the clock display showed day 1.", \'id\': \'182/B\', \'input_format\': "The first line contains the single number d — the maximum number of the day that Vasya\'s clock can show (1 ≤ d ≤ 106).\\n\\nThe second line contains a single integer n — the number of months in the year (1 ≤ n ≤ 2000).\\n\\nThe third line contains n space-separated integers: ai (1 ≤ ai ≤ d) — the number of days in each month in the order in which they follow, starting from the first one.", \'output_format\': \'Print a single number — the number of times Vasya manually increased the day number by one throughout the last year.\'}, \'195A\': {\'description\': \'Valeric and Valerko missed the last Euro football game, so they decided to watch the game\\\'s key moments on the Net. They want to start watching as soon as possible but the connection speed is too low. If they turn on the video right now, it will "hang up" as the size of data to watch per second will be more than the size of downloaded data per second.\\n\\nThe guys want to watch the whole video without any pauses, so they have to wait some integer number of seconds for a part of the video to download. After this number of seconds passes, they can start watching. Waiting for the whole video to download isn\\\'t necessary as the video can download after the guys started to watch.\\n\\nLet\\\'s suppose that video\\\'s length is c seconds and Valeric and Valerko wait t seconds before the watching. Then for any moment of time t0, t ≤ t0 ≤ c + t, the following condition must fulfill: the size of data received in t0 seconds is not less than the size of data needed to watch t0 - t seconds of the video.\\n\\nOf course, the guys want to wait as little as possible, so your task is to find the minimum integer number of seconds to wait before turning the video on. The guys must watch the video without pauses.\', \'id\': \'195/A\', \'input_format\': "The first line contains three space-separated integers a, b and c (1 ≤ a, b, c ≤ 1000, a > b). The first number (a) denotes the size of data needed to watch one second of the video. The second number (b) denotes the size of data Valeric and Valerko can download from the Net per second. The third number (c) denotes the video\'s length in seconds.", \'output_format\': \'Print a single number — the minimum integer number of seconds that Valeric and Valerko must wait to watch football without pauses.\'}, \'1A\': {\'description\': "Theatre Square in the capital city of Berland has a rectangular shape with the size n × m meters. On the occasion of the city\'s anniversary, a decision was taken to pave the Square with square granite flagstones. Each flagstone is of the size a × a.\\n\\nWhat is the least number of flagstones needed to pave the Square? It\'s allowed to cover the surface larger than the Theatre Square, but the Square has to be covered. It\'s not allowed to break the flagstones. The sides of flagstones should be parallel to the sides of the Square.", \'id\': \'1/A\', \'input_format\': \'The input contains three positive integer numbers in the first line: n,  m and a (1 ≤  n, m, a ≤ 109).\', \'output_format\': \'Write the needed number of flagstones.\'}, \'219A\': {\'description\': \'A string is called a k-string if it can be represented as k concatenated copies of some string. For example, the string "aabaabaabaab" is at the same time a 1-string, a 2-string and a 4-string, but it is not a 3-string, a 5-string, or a 6-string and so on. Obviously any string is a 1-string.\\n\\nYou are given a string s, consisting of lowercase English letters and a positive integer k. Your task is to reorder the letters in the string s in such a way that the resulting string is a k-string.\', \'id\': \'219/A\', \'input_format\': \'The first input line contains integer k (1 ≤ k ≤ 1000). The second line contains s, all characters in s are lowercase English letters. The string length s satisfies the inequality 1 ≤ |s| ≤ 1000, where |s| is the length of string s.\', \'output_format\': \'Rearrange the letters in string s in such a way that the result is a k-string. Print the result on a single output line. If there are multiple solutions, print any of them.\\n\\nIf the solution doesn\\\'t exist, print "-1" (without quotes).\'}, \'230A\': {\'description\': "Kirito is stuck on a level of the MMORPG he is playing now. To move on in the game, he\'s got to defeat all n dragons that live on this level. Kirito and the dragons have strength, which is represented by an integer. In the duel between two opponents the duel\'s outcome is determined by their strength. Initially, Kirito\'s strength equals s.\\n\\nIf Kirito starts duelling with the i-th (1 ≤ i ≤ n) dragon and Kirito\'s strength is not greater than the dragon\'s strength xi, then Kirito loses the duel and dies. But if Kirito\'s strength is greater than the dragon\'s strength, then he defeats the dragon and gets a bonus strength increase by yi.\\n\\nKirito can fight the dragons in any order. Determine whether he can move on to the next level of the game, that is, defeat all dragons without a single loss.", \'id\': \'230/A\', \'input_format\': "The first line contains two space-separated integers s and n (1 ≤ s ≤ 104, 1 ≤ n ≤ 103). Then n lines follow: the i-th line contains space-separated integers xi and yi (1 ≤ xi ≤ 104, 0 ≤ yi ≤ 104) — the i-th dragon\'s strength and the bonus for defeating it.", \'output_format\': \'On a single line print "YES" (without the quotes), if Kirito can move on to the next level and print "NO" (without the quotes), if he can\\\'t.\'}, \'237A\': {\'description\': "Valera runs a 24/7 fast food cafe. He magically learned that next day n people will visit his cafe. For each person we know the arrival time: the i-th person comes exactly at hi hours mi minutes. The cafe spends less than a minute to serve each client, but if a client comes in and sees that there is no free cash, than he doesn\'t want to wait and leaves the cafe immediately.\\n\\nValera is very greedy, so he wants to serve all n customers next day (and get more profit). However, for that he needs to ensure that at each moment of time the number of working cashes is no less than the number of clients in the cafe.\\n\\nHelp Valera count the minimum number of cashes to work at his cafe next day, so that they can serve all visitors.", \'id\': \'237/A\', \'input_format\': \'The first line contains a single integer n (1 ≤ n ≤ 105), that is the number of cafe visitors.\\n\\nEach of the following n lines has two space-separated integers hi and mi (0 ≤ hi ≤ 23;\\xa00 ≤ mi ≤ 59), representing the time when the i-th person comes into the cafe.\\n\\nNote that the time is given in the chronological order. All time is given within one 24-hour period.\', \'output_format\': \'Print a single integer — the minimum number of cashes, needed to serve all clients next day.\'}, \'259A\': {\'description\': \'The Little Elephant loves chess very much.\\n\\nOne day the Little Elephant and his friend decided to play chess. They\\\'ve got the chess pieces but the board is a problem. They\\\'ve got an 8 × 8 checkered board, each square is painted either black or white. The Little Elephant and his friend know that a proper chessboard doesn\\\'t have any side-adjacent cells with the same color and the upper left cell is white. To play chess, they want to make the board they have a proper chessboard. For that the friends can choose any row of the board and cyclically shift the cells of the chosen row, that is, put the last (rightmost) square on the first place in the row and shift the others one position to the right. You can run the described operation multiple times (or not run it at all).\\n\\nFor example, if the first line of the board looks like that "BBBBBBWW" (the white cells of the line are marked with character "W", the black cells are marked with character "B"), then after one cyclic shift it will look like that "WBBBBBBW".\\n\\nHelp the Little Elephant and his friend to find out whether they can use any number of the described operations to turn the board they have into a proper chessboard.\', \'id\': \'259/A\', \'input_format\': \'The input consists of exactly eight lines. Each line contains exactly eight characters "W" or "B" without any spaces: the j-th character in the i-th line stands for the color of the j-th cell of the i-th row of the elephants\\\' board. Character "W" stands for the white color, character "B" stands for the black color.\\n\\nConsider the rows of the board numbered from 1 to 8 from top to bottom, and the columns — from 1 to 8 from left to right. The given board can initially be a proper chessboard.\', \'output_format\': \'In a single line print "YES" (without the quotes), if we can make the board a proper chessboard and "NO" (without the quotes) otherwise.\'}, \'265B\': {\'description\': "Squirrel Liss loves nuts. There are n trees (numbered 1 to n from west to east) along a street and there is a delicious nut on the top of each tree. The height of the tree i is hi. Liss wants to eat all nuts.\\n\\nNow Liss is on the root of the tree with the number 1. In one second Liss can perform one of the following actions:\\n\\n- Walk up or down one unit on a tree.\\n- Eat a nut on the top of the current tree.\\n- Jump to the next tree. In this action the height of Liss doesn\'t change. More formally, when Liss is at height h of the tree i (1\\u2009≤\\u2009i\\u2009≤\\u2009n\\u2009-\\u20091), she jumps to height h of the tree i\\u2009+\\u20091. This action can\'t be performed if h\\u2009>\\u2009hi\\u2009+\\u20091.\\n\\nCompute the minimal time (in seconds) required to eat all nuts.", \'id\': \'265/B\', \'input_format\': \'The first line contains an integer n (1  ≤  n ≤ 105) — the number of trees.\\n\\nNext n lines contains the height of trees: i-th line contains an integer hi (1 ≤ hi ≤ 104) — the height of the tree with the number i.\', \'output_format\': \'Print a single integer — the minimal time required to eat all nuts in seconds.\'}, \'268B\': {\'description\': "Manao is trying to open a rather challenging lock. The lock has n buttons on it and to open it, you should press the buttons in a certain order to open the lock. When you push some button, it either stays pressed into the lock (that means that you\'ve guessed correctly and pushed the button that goes next in the sequence), or all pressed buttons return to the initial position. When all buttons are pressed into the lock at once, the lock opens.\\n\\nConsider an example with three buttons. Let\'s say that the opening sequence is: {2, 3, 1}. If you first press buttons 1 or 3, the buttons unpress immediately. If you first press button 2, it stays pressed. If you press 1 after 2, all buttons unpress. If you press 3 after 2, buttons 3 and 2 stay pressed. As soon as you\'ve got two pressed buttons, you only need to press button 1 to open the lock.\\n\\nManao doesn\'t know the opening sequence. But he is really smart and he is going to act in the optimal way. Calculate the number of times he\'s got to push a button in order to open the lock in the worst-case scenario.", \'id\': \'268/B\', \'input_format\': \'A single line contains integer n (1 ≤ n ≤ 2000) — the number of buttons the lock has.\', \'output_format\': \'In a single line print the number of times Manao has to push a button in the worst-case scenario.\'}, \'272A\': {\'description\': "Dima and his friends have been playing hide and seek at Dima\'s place all night. As a result, Dima\'s place got messy. In the morning they decided that they need to clean the place.\\n\\nTo decide who exactly would clean the apartment, the friends want to play a counting-out game. First, all the guys stand in a circle, and then each of them shows some number of fingers on one hand (one to five), and then the boys count in a circle, starting from Dima, the number of people, respective to the total number of fingers shown. The person on who the countdown stops will clean the apartment.\\n\\nFor example, if Dima and one of his friends played hide and seek, and 7 fingers were shown during the counting-out, then Dima would clean the place. If there were 2 or say, 8 fingers shown, then his friend would clean the place.\\n\\nDima knows how many fingers each of his friends will show during the counting-out. Now he is interested in the number of ways to show some number of fingers on one hand (one to five), so that he did not have to clean the place. Help Dima.", \'id\': \'272/A\', \'input_format\': "The first line contains integer n (1 ≤ n ≤ 100) — the number of Dima\'s friends. Dima himself isn\'t considered to be his own friend. The second line contains n positive integers, not exceeding 5, representing, how many fingers the Dima\'s friends will show.\\n\\nThe numbers in the lines are separated by a single space.", \'output_format\': \'In a single line print the answer to the problem.\'}, \'284B\': {\'description\': \'There are n cows playing poker at a table. For the current betting phase, each player\\\'s status is either "ALLIN", "IN", or "FOLDED", and does not change throughout the phase. To increase the suspense, a player whose current status is not "FOLDED" may show his/her hand to the table. However, so as not to affect any betting decisions, he/she may only do so if all other players have a status of either "ALLIN" or "FOLDED". The player\\\'s own status may be either "ALLIN" or "IN".\\n\\nFind the number of cows that can currently show their hands without affecting any betting decisions.\', \'id\': \'284/B\', \'input_format\': \'The first line contains a single integer, n (2 ≤ n ≤ 2·105). The second line contains n characters, each either "A", "I", or "F". The i-th character is "A" if the i-th player\\\'s status is "ALLIN", "I" if the i-th player\\\'s status is "IN", or "F" if the i-th player\\\'s status is "FOLDED".\', \'output_format\': \'The first line should contain a single integer denoting the number of players that can currently show their hands.\'}, \'299A\': {\'description\': \'Ksusha is a beginner coder. Today she starts studying arrays. She has array a1, a2, ..., an, consisting of n positive integers.\\n\\nHer university teacher gave her a task. Find such number in the array, that all array elements are divisible by it. Help her and find the number!\', \'id\': \'299/A\', \'input_format\': \'The first line contains integer n (1 ≤ n ≤ 105), showing how many numbers the array has. The next line contains integers a1, a2, ..., an (1 ≤ ai ≤ 109) — the array elements.\', \'output_format\': "Print a single integer — the number from the array, such that all array elements are divisible by it. If such number doesn\'t exist, print -1.\\n\\nIf there are multiple answers, you are allowed to print any of them."}, \'29A\': {\'description\': "In a Berland\'s zoo there is an enclosure with camels. It is known that camels like to spit. Bob watched these interesting animals for the whole day and registered in his notepad where each animal spitted. Now he wants to know if in the zoo there are two camels, which spitted at each other. Help him to solve this task.\\n\\nThe trajectory of a camel\'s spit is an arc, i.e. if the camel in position x spits d meters right, he can hit only the camel in position x + d, if such a camel exists.", \'id\': \'29/A\', \'input_format\': "The first line contains integer n (1 ≤ n ≤ 100) — the amount of camels in the zoo. Each of the following n lines contains two integers xi and di ( - 104 ≤ xi ≤ 104, 1 ≤ |di| ≤ 2·104) — records in Bob\'s notepad. xi is a position of the i-th camel, and di is a distance at which the i-th camel spitted. Positive values of di correspond to the spits right, negative values correspond to the spits left. No two camels may stand in the same position.", \'output_format\': \'If there are two camels, which spitted at each other, output YES. Otherwise, output NO.\'}, \'336A\': {\'description\': "Vasily the bear has a favorite rectangle, it has one vertex at point (0, 0), and the opposite vertex at point (x, y). Of course, the sides of Vasya\'s favorite rectangle are parallel to the coordinate axes.\\n\\nVasya also loves triangles, if the triangles have one vertex at point B = (0, 0). That\'s why today he asks you to find two points A = (x1, y1) and C = (x2, y2), such that the following conditions hold:\\n\\n- the coordinates of points: x1, x2, y1, y2 are integers. Besides, the following inequation holds: x1\\u2009<\\u2009x2;\\n- the triangle formed by point A, B and C is rectangular and isosceles ($$\\\\angle ABC$$ is right);\\n- all points of the favorite rectangle are located inside or on the border of triangle ABC;\\n- the area of triangle ABC is as small as possible.\\n\\nHelp the bear, find the required points. It is not so hard to proof that these points are unique.", \'id\': \'336/A\', \'input_format\': \'The first line contains two integers x, y ( - 109 ≤ x, y ≤ 109, x ≠ 0, y ≠ 0).\', \'output_format\': \'Print in the single line four integers x1, y1, x2, y2 — the coordinates of the required points.\'}, \'339B\': {\'description\': "Xenia lives in a city that has n houses built along the main ringroad. The ringroad houses are numbered 1 through n in the clockwise order. The ringroad traffic is one way and also is clockwise.\\n\\nXenia has recently moved into the ringroad house number 1. As a result, she\'s got m things to do. In order to complete the i-th task, she needs to be in the house number ai and complete all tasks with numbers less than i. Initially, Xenia is in the house number 1, find the minimum time she needs to complete all her tasks if moving from a house to a neighboring one along the ringroad takes one unit of time.", \'id\': \'339/B\', \'input_format\': \'The first line contains two integers n and m (2 ≤ n ≤ 105, 1 ≤ m ≤ 105). The second line contains m integers a1, a2, ..., am (1 ≤ ai ≤ n). Note that Xenia can have multiple consecutive tasks in one house.\', \'output_format\': \'Print a single integer — the time Xenia needs to complete all tasks.\\n\\nPlease, do not use the %lld specifier to read or write 64-bit integers in С++. It is preferred to use the cin, cout streams or the %I64d specifier.\'}, \'352A\': {\'description\': "Jeff\'s got n cards, each card contains either digit 0, or digit 5. Jeff can choose several cards and put them in a line so that he gets some number. What is the largest possible number divisible by 90 Jeff can make from the cards he\'s got?\\n\\nJeff must make the number without leading zero. At that, we assume that number 0 doesn\'t contain any leading zeroes. Jeff doesn\'t have to use all the cards.", \'id\': \'352/A\', \'input_format\': \'The first line contains integer n (1 ≤ n ≤ 103). The next line contains n integers a1, a2, ..., an (ai = 0 or ai = 5). Number ai represents the digit that is written on the i-th card.\', \'output_format\': "In a single line print the answer to the problem — the maximum number, divisible by 90. If you can\'t make any divisible by 90 number from the cards, print -1."}, \'359A\': {\'description\': "Simon has a rectangular table consisting of n rows and m columns. Simon numbered the rows of the table from top to bottom starting from one and the columns — from left to right starting from one. We\'ll represent the cell on the x-th row and the y-th column as a pair of numbers (x, y). The table corners are cells: (1, 1), (n, 1), (1, m), (n, m).\\n\\nSimon thinks that some cells in this table are good. Besides, it\'s known that no good cell is the corner of the table.\\n\\nInitially, all cells of the table are colorless. Simon wants to color all cells of his table. In one move, he can choose any good cell of table (x1, y1), an arbitrary corner of the table (x2, y2) and color all cells of the table (p, q), which meet both inequations: min(x1, x2) ≤ p ≤ max(x1, x2), min(y1, y2) ≤ q ≤ max(y1, y2).\\n\\nHelp Simon! Find the minimum number of operations needed to color all cells of the table. Note that you can color one cell multiple times.", \'id\': \'359/A\', \'input_format\': "The first line contains exactly two integers n, m (3 ≤ n, m ≤ 50).\\n\\nNext n lines contain the description of the table cells. Specifically, the i-th line contains m space-separated integers ai1, ai2, ..., aim. If aij equals zero, then cell (i, j) isn\'t good. Otherwise aij equals one. It is guaranteed that at least one cell is good. It is guaranteed that no good cell is a corner.", \'output_format\': \'Print a single number — the minimum number of operations Simon needs to carry out his idea.\'}, \'368A\': {\'description\': "Sereja owns a restaurant for n people. The restaurant hall has a coat rack with n hooks. Each restaurant visitor can use a hook to hang his clothes on it. Using the i-th hook costs ai rubles. Only one person can hang clothes on one hook.\\n\\nTonight Sereja expects m guests in the restaurant. Naturally, each guest wants to hang his clothes on an available hook with minimum price (if there are multiple such hooks, he chooses any of them). However if the moment a guest arrives the rack has no available hooks, Sereja must pay a d ruble fine to the guest.\\n\\nHelp Sereja find out the profit in rubles (possibly negative) that he will get tonight. You can assume that before the guests arrive, all hooks on the rack are available, all guests come at different time, nobody besides the m guests is visiting Sereja\'s restaurant tonight.", \'id\': \'368/A\', \'input_format\': \'The first line contains two integers n and d (1 ≤ n, d ≤ 100). The next line contains integers a1, a2, ..., an (1 ≤ ai ≤ 100). The third line contains integer m (1 ≤ m ≤ 100).\', \'output_format\': \'In a single line print a single integer — the answer to the problem.\'}, \'371A\': {\'description\': \'This task will exclusively concentrate only on the arrays where all elements equal 1 and/or 2.\\n\\nArray a is k-period if its length is divisible by k and there is such array b of length k, that a is represented by array b written exactly $$\\\\pi_{k}$$ times consecutively. In other words, array a is k-periodic, if it has period of length k.\\n\\nFor example, any array is n-periodic, where n is the array length. Array [2, 1, 2, 1, 2, 1] is at the same time 2-periodic and 6-periodic and array [1, 2, 1, 1, 2, 1, 1, 2, 1] is at the same time 3-periodic and 9-periodic.\\n\\nFor the given array a, consisting only of numbers one and two, find the minimum number of elements to change to make the array k-periodic. If the array already is k-periodic, then the required value equals 0.\', \'id\': \'371/A\', \'input_format\': \'The first line of the input contains a pair of integers n, k (1 ≤ k ≤ n ≤ 100), where n is the length of the array and the value n is divisible by k. The second line contains the sequence of elements of the given array a1, a2, ..., an (1 ≤ ai ≤ 2), ai is the i-th element of the array.\', \'output_format\': \'Print the minimum number of array elements we need to change to make the array k-periodic. If the array already is k-periodic, then print 0.\'}, \'379A\': {\'description\': \'Vasily the Programmer loves romance, so this year he decided to illuminate his room with candles.\\n\\nVasily has a candles.When Vasily lights up a new candle, it first burns for an hour and then it goes out. Vasily is smart, so he can make b went out candles into a new candle. As a result, this new candle can be used like any other new candle.\\n\\nNow Vasily wonders: for how many hours can his candles light up the room if he acts optimally well? Help him find this number.\', \'id\': \'379/A\', \'input_format\': \'The single line contains two integers, a and b (1 ≤ a ≤ 1000;\\xa02 ≤ b ≤ 1000).\', \'output_format\': \'Print a single integer — the number of hours Vasily can light up the room for.\'}, \'37A\': {\'description\': \'Little Vasya has received a young builder’s kit. The kit consists of several wooden bars, the lengths of all of them are known. The bars can be put one on the top of the other if their lengths are the same.\\n\\nVasya wants to construct the minimal number of towers from the bars. Help Vasya to use the bars in the best way possible.\', \'id\': \'37/A\', \'input_format\': \'The first line contains an integer N (1 ≤ N ≤ 1000) — the number of bars at Vasya’s disposal. The second line contains N space-separated integers li — the lengths of the bars. All the lengths are natural numbers not exceeding 1000.\', \'output_format\': \'In one line output two numbers — the height of the largest tower and their total number. Remember that Vasya should use all the bars.\'}, \'385A\': {\'description\': "The bear decided to store some raspberry for the winter. He cunningly found out the price for a barrel of honey in kilos of raspberry for each of the following n days. According to the bear\'s data, on the i-th (1 ≤ i ≤ n) day, the price for one barrel of honey is going to is xi kilos of raspberry.\\n\\nUnfortunately, the bear has neither a honey barrel, nor the raspberry. At the same time, the bear\'s got a friend who is ready to lend him a barrel of honey for exactly one day for c kilograms of raspberry. That\'s why the bear came up with a smart plan. He wants to choose some day d (1 ≤ d < n), lent a barrel of honey and immediately (on day d) sell it according to a daily exchange rate. The next day (d + 1) the bear wants to buy a new barrel of honey according to a daily exchange rate (as he\'s got some raspberry left from selling the previous barrel) and immediately (on day d + 1) give his friend the borrowed barrel of honey as well as c kilograms of raspberry for renting the barrel.\\n\\nThe bear wants to execute his plan at most once and then hibernate. What maximum number of kilograms of raspberry can he earn? Note that if at some point of the plan the bear runs out of the raspberry, then he won\'t execute such a plan.", \'id\': \'385/A\', \'input_format\': \'The first line contains two space-separated integers, n and c (2 ≤ n ≤ 100, 0 ≤ c ≤ 100), — the number of days and the number of kilos of raspberry that the bear should give for borrowing the barrel.\\n\\nThe second line contains n space-separated integers x1, x2, ..., xn (0 ≤ xi ≤ 100), the price of a honey barrel on day i.\', \'output_format\': \'Print a single integer — the answer to the problem.\'}, \'389A\': {\'description\': \'Fox Ciel is playing a game with numbers now.\\n\\nCiel has n positive integers: x1, x2, ..., xn. She can do the following operation as many times as needed: select two different indexes i and j such that xi > xj hold, and then apply assignment xi = xi - xj. The goal is to make the sum of all numbers as small as possible.\\n\\nPlease help Ciel to find this minimal sum.\', \'id\': \'389/A\', \'input_format\': \'The first line contains an integer n (2 ≤ n ≤ 100). Then the second line contains n integers: x1, x2, ..., xn (1 ≤ xi ≤ 100).\', \'output_format\': \'Output a single integer — the required minimal sum.\'}, \'400A\': {\'description\': \'There always is something to choose from! And now, instead of "Noughts and Crosses", Inna choose a very unusual upgrade of this game. The rules of the game are given below:\\n\\nThere is one person playing the game. Before the beginning of the game he puts 12 cards in a row on the table. Each card contains a character: "X" or "O". Then the player chooses two positive integers a and b (a·b = 12), after that he makes a table of size a × b from the cards he put on the table as follows: the first b cards form the first row of the table, the second b cards form the second row of the table and so on, the last b cards form the last (number a) row of the table. The player wins if some column of the table contain characters "X" on all cards. Otherwise, the player loses.\\n\\nInna has already put 12 cards on the table in a row. But unfortunately, she doesn\\\'t know what numbers a and b to choose. Help her win the game: print to her all the possible ways of numbers a, b that she can choose and win.\', \'id\': \'400/A\', \'input_format\': \'The first line of the input contains integer t (1 ≤ t ≤ 100). This value shows the number of sets of test data in the input. Next follows the description of each of the t tests on a separate line.\\n\\nThe description of each test is a string consisting of 12 characters, each character is either "X", or "O". The i-th character of the string shows the character that is written on the i-th card from the start.\', \'output_format\': \'For each test, print the answer to the test on a single line. The first number in the line must represent the number of distinct ways to choose the pair a, b. Next, print on this line the pairs in the format axb. Print the pairs in the order of increasing first parameter (a). Separate the pairs in the line by whitespaces.\'}, \'404A\': {\'description\': \'Valera is a little boy. Yesterday he got a huge Math hometask at school, so Valera didn\\\'t have enough time to properly learn the English alphabet for his English lesson. Unfortunately, the English teacher decided to have a test on alphabet today. At the test Valera got a square piece of squared paper. The length of the side equals n squares (n is an odd number) and each unit square contains some small letter of the English alphabet.\\n\\nValera needs to know if the letters written on the square piece of paper form letter "X". Valera\\\'s teacher thinks that the letters on the piece of paper form an "X", if:\\n\\n- on both diagonals of the square paper all letters are the same;\\n- all other squares of the paper (they are not on the diagonals) contain the same letter that is different from the letters on the diagonals.\\n\\nHelp Valera, write the program that completes the described task for him.\', \'id\': \'404/A\', \'input_format\': "The first line contains integer n (3 ≤ n < 300; n is odd). Each of the next n lines contains n small English letters — the description of Valera\'s paper.", \'output_format\': \'Print string "YES", if the letters on the paper form letter "X". Otherwise, print string "NO". Print the strings without quotes.\'}, \'435A\': {\'description\': "It\'s that time of the year when the Russians flood their countryside summer cottages (dachas) and the bus stop has a lot of people. People rarely go to the dacha on their own, it\'s usually a group, so the people stand in queue by groups.\\n\\nThe bus stop queue has n groups of people. The i-th group from the beginning has ai people. Every 30 minutes an empty bus arrives at the bus stop, it can carry at most m people. Naturally, the people from the first group enter the bus first. Then go the people from the second group and so on. Note that the order of groups in the queue never changes. Moreover, if some group cannot fit all of its members into the current bus, it waits for the next bus together with other groups standing after it in the queue.\\n\\nYour task is to determine how many buses is needed to transport all n groups to the dacha countryside.", \'id\': \'435/A\', \'input_format\': \'The first line contains two integers n and m (1 ≤ n, m ≤ 100). The next line contains n integers: a1, a2, ..., an (1 ≤ ai ≤ m).\', \'output_format\': \'Print a single integer — the number of buses that is needed to transport all n groups to the dacha countryside.\'}, \'43A\': {\'description\': "One day Vasya decided to have a look at the results of Berland 1910 Football Championship’s finals. Unfortunately he didn\'t find the overall score of the match; however, he got hold of a profound description of the match\'s process. On the whole there are n lines in that description each of which described one goal. Every goal was marked with the name of the team that had scored it. Help Vasya, learn the name of the team that won the finals. It is guaranteed that the match did not end in a tie.", \'id\': \'43/A\', \'input_format\': \'The first line contains an integer n (1 ≤ n ≤ 100) — the number of lines in the description. Then follow n lines — for each goal the names of the teams that scored it. The names are non-empty lines consisting of uppercase Latin letters whose lengths do not exceed 10 symbols. It is guaranteed that the match did not end in a tie and the description contains no more than two different teams.\', \'output_format\': \'Print the name of the winning team. We remind you that in football the team that scores more goals is considered the winner.\'}, \'441A\': {\'description\': \'Valera is a collector. Once he wanted to expand his collection with exactly one antique item.\\n\\nValera knows n sellers of antiques, the i-th of them auctioned ki items. Currently the auction price of the j-th object of the i-th seller is sij. Valera gets on well with each of the n sellers. He is perfectly sure that if he outbids the current price of one of the items in the auction (in other words, offers the seller the money that is strictly greater than the current price of the item at the auction), the seller of the object will immediately sign a contract with him.\\n\\nUnfortunately, Valera has only v units of money. Help him to determine which of the n sellers he can make a deal with.\', \'id\': \'441/A\', \'input_format\': \'The first line contains two space-separated integers n, v (1 ≤ n ≤ 50;\\xa0104 ≤ v ≤ 106) — the number of sellers and the units of money the Valera has.\\n\\nThen n lines follow. The i-th line first contains integer ki (1 ≤ ki ≤ 50) the number of items of the i-th seller. Then go ki space-separated integers si1, si2, ..., siki (104 ≤ sij ≤ 106) — the current prices of the items of the i-th seller.\', \'output_format\': \'In the first line, print integer p — the number of sellers with who Valera can make a deal.\\n\\nIn the second line print p space-separated integers q1, q2, ..., qp (1 ≤ qi ≤ n) — the numbers of the sellers with who Valera can make a deal. Print the numbers of the sellers in the increasing order.\'}, \'447B\': {\'description\': \'DZY loves collecting special strings which only contain lowercase letters. For each lowercase letter c DZY knows its value wc. For each special string s = s1s2... s|s| (|s| is the length of the string) he represents its value with a function f(s), where\\n\\n$$f(s) = \\\\sum_{i=1}^{|s|} (w_{s_i} \\\\cdot i).$$\\n\\nNow DZY has a string s. He wants to insert k lowercase letters into this string in order to get the largest possible value of the resulting string. Can you help him calculate the largest possible value he could get?\', \'id\': \'447/B\', \'input_format\': "The first line contains a single string s\\xa0(1 ≤ |s| ≤ 103).\\n\\nThe second line contains a single integer k\\xa0(0 ≤ k ≤ 103).\\n\\nThe third line contains twenty-six integers from wa to wz. Each such number is non-negative and doesn\'t exceed 1000.", \'output_format\': \'Print a single integer — the largest possible value of the resulting string DZY could get.\'}, \'452A\': {\'description\': \'You are solving the crossword problem K from IPSC 2014. You solved all the clues except for one: who does Eevee evolve into? You are not very into pokemons, but quick googling helped you find out, that Eevee can evolve into eight different pokemons: Vaporeon, Jolteon, Flareon, Espeon, Umbreon, Leafeon, Glaceon, and Sylveon.\\n\\nYou know the length of the word in the crossword, and you already know some letters. Designers of the crossword made sure that the answer is unambiguous, so you can assume that exactly one pokemon out of the 8 that Eevee evolves into fits the length and the letters given. Your task is to find it.\', \'id\': \'452/A\', \'input_format\': \'First line contains an integer n (6 ≤ n ≤ 8) – the length of the string.\\n\\nNext line contains a string consisting of n characters, each of which is either a lower case english letter (indicating a known letter) or a dot character (indicating an empty cell in the crossword).\', \'output_format\': \'Print a name of the pokemon that Eevee can evolve into that matches the pattern in the input. Use lower case letters only to print the name (in particular, do not capitalize the first letter).\'}, \'462A\': {\'description\': "Toastman came up with a very easy task. He gives it to Appleman, but Appleman doesn\'t know how to solve it. Can you help him?\\n\\nGiven a n × n checkerboard. Each cell of the board has either character \'x\', or character \'o\'. Is it true that each cell of the board has even number of adjacent cells with \'o\'? Two cells of the board are adjacent if they share a side.", \'id\': \'462/A\', \'input_format\': "The first line contains an integer n (1 ≤ n ≤ 100). Then n lines follow containing the description of the checkerboard. Each of them contains n characters (either \'x\' or \'o\') without spaces.", \'output_format\': \'Print "YES" or "NO" (without the quotes) depending on the answer to the problem.\'}, \'465B\': {\'description\': "Over time, Alexey\'s mail box got littered with too many letters. Some of them are read, while others are unread.\\n\\nAlexey\'s mail program can either show a list of all letters or show the content of a single letter. As soon as the program shows the content of an unread letter, it becomes read letter (if the program shows the content of a read letter nothing happens). In one click he can do any of the following operations:\\n\\n- Move from the list of letters to the content of any single letter.\\n- Return to the list of letters from single letter viewing mode.\\n- In single letter viewing mode, move to the next or to the previous letter in the list. You cannot move from the first letter to the previous one or from the last letter to the next one.\\n\\nThe program cannot delete the letters from the list or rearrange them.\\n\\nAlexey wants to read all the unread letters and go watch football. Now he is viewing the list of all letters and for each letter he can see if it is read or unread. What minimum number of operations does Alexey need to perform to read all unread letters?", \'id\': \'465/B\', \'input_format\': \'The first line contains a single integer n (1 ≤ n ≤ 1000) — the number of letters in the mailbox.\\n\\nThe second line contains n space-separated integers (zeros and ones) — the state of the letter list. The i-th number equals either 1, if the i-th number is unread, or 0, if the i-th letter is read.\', \'output_format\': \'Print a single number — the minimum number of operations needed to make all the letters read.\'}, \'499A\': {\'description\': \'You have decided to watch the best moments of some movie. There are two buttons on your player:\\n\\n1. Watch the current minute of the movie. By pressing this button, you watch the current minute of the movie and the player automatically proceeds to the next minute of the movie.\\n2. Skip exactly x minutes of the movie (x is some fixed positive integer). If the player is now at the t-th minute of the movie, then as a result of pressing this button, it proceeds to the minute (t\\u2009+\\u2009x).\\n\\nInitially the movie is turned on in the player on the first minute, and you want to watch exactly n best moments of the movie, the i-th best moment starts at the li-th minute and ends at the ri-th minute (more formally, the i-th best moment consists of minutes: li, li + 1, ..., ri).\\n\\nDetermine, what is the minimum number of minutes of the movie you have to watch if you want to watch all the best moments?\', \'id\': \'499/A\', \'input_format\': \'The first line contains two space-separated integers n, x (1 ≤ n ≤ 50, 1 ≤ x ≤ 105) — the number of the best moments of the movie and the value of x for the second button.\\n\\nThe following n lines contain the descriptions of the best moments of the movie, the i-th line of the description contains two integers separated by a space li, ri (1 ≤ li ≤ ri ≤ 105).\\n\\nIt is guaranteed that for all integers i from 2 to n the following condition holds: ri - 1 < li.\', \'output_format\': \'Output a single number — the answer to the problem.\'}, \'499B\': {\'description\': \'You have a new professor of graph theory and he speaks very quickly. You come up with the following plan to keep up with his lecture and make notes.\\n\\nYou know two languages, and the professor is giving the lecture in the first one. The words in both languages consist of lowercase English characters, each language consists of several words. For each language, all words are distinct, i.e. they are spelled differently. Moreover, the words of these languages have a one-to-one correspondence, that is, for each word in each language, there exists exactly one word in the other language having has the same meaning.\\n\\nYou can write down every word the professor says in either the first language or the second language. Of course, during the lecture you write down each word in the language in which the word is shorter. In case of equal lengths of the corresponding words you prefer the word of the first language.\\n\\nYou are given the text of the lecture the professor is going to read. Find out how the lecture will be recorded in your notes.\', \'id\': \'499/B\', \'input_format\': "The first line contains two integers, n and m (1 ≤ n ≤ 3000, 1 ≤ m ≤ 3000) — the number of words in the professor\'s lecture and the number of words in each of these languages.\\n\\nThe following m lines contain the words. The i-th line contains two strings ai, bi meaning that the word ai belongs to the first language, the word bi belongs to the second language, and these two words have the same meaning. It is guaranteed that no word occurs in both languages, and each word occurs in its language exactly once.\\n\\nThe next line contains n space-separated strings c1, c2, ..., cn — the text of the lecture. It is guaranteed that each of the strings ci belongs to the set of strings {a1, a2, ... am}.\\n\\nAll the strings in the input are non-empty, each consisting of no more than 10 lowercase English letters.", \'output_format\': \'Output exactly n words: how you will record the lecture in your notebook. Output the words of the lecture in the same order as in the input.\'}, \'500A\': {\'description\': "New Year is coming in Line World! In this world, there are n cells numbered by integers from 1 to n, as a 1 × n board. People live in cells. However, it was hard to move between distinct cells, because of the difficulty of escaping the cell. People wanted to meet people who live in other cells.\\n\\nSo, user tncks0121 has made a transportation system to move between these cells, to celebrate the New Year. First, he thought of n - 1 positive integers a1, a2, ..., an - 1. For every integer i where 1 ≤ i ≤ n - 1 the condition 1 ≤ ai ≤ n - i holds. Next, he made n - 1 portals, numbered by integers from 1 to n - 1. The i-th (1 ≤ i ≤ n - 1) portal connects cell i and cell (i + ai), and one can travel from cell i to cell (i + ai) using the i-th portal. Unfortunately, one cannot use the portal backwards, which means one cannot move from cell (i + ai) to cell i using the i-th portal. It is easy to see that because of condition 1 ≤ ai ≤ n - i one can\'t leave the Line World using portals.\\n\\nCurrently, I am standing at cell 1, and I want to go to cell t. However, I don\'t know whether it is possible to go there. Please determine whether I can go to cell t by only using the construted transportation system.", \'id\': \'500/A\', \'input_format\': \'The first line contains two space-separated integers n (3 ≤ n ≤ 3 × 104) and t (2 ≤ t ≤ n) — the number of cells, and the index of the cell which I want to go to.\\n\\nThe second line contains n - 1 space-separated integers a1, a2, ..., an - 1 (1 ≤ ai ≤ n - i). It is guaranteed, that using the given transportation system, one cannot leave the Line World.\', \'output_format\': \'If I can go to cell t using the transportation system, print "YES". Otherwise, print "NO".\'}, \'535A\': {\'description\': "Today Tavas got his test result as an integer score and he wants to share it with his girlfriend, Nafas.\\n\\nHis phone operating system is Tavdroid, and its keyboard doesn\'t have any digits! He wants to share his score with Nafas via text, so he has no choice but to send this number using words.\\n\\nHe ate coffee mix without water again, so right now he\'s really messed up and can\'t think.\\n\\nYour task is to help him by telling him what to type.", \'id\': \'535/A\', \'input_format\': "The first and only line of input contains an integer s (0 ≤ s ≤ 99), Tavas\'s score.", \'output_format\': "In the first and only line of output, print a single string consisting only from English lowercase letters and hyphens (\'-\'). Do not use spaces."}, \'560A\': {\'description\': \'A magic island Geraldion, where Gerald lives, has its own currency system. It uses banknotes of several values. But the problem is, the system is not perfect and sometimes it happens that Geraldionians cannot express a certain sum of money with any set of banknotes. Of course, they can use any number of banknotes of each value. Such sum is called unfortunate. Gerald wondered: what is the minimum unfortunate sum?\', \'id\': \'560/A\', \'input_format\': \'The first line contains number n (1 ≤ n ≤ 1000) — the number of values of the banknotes that used in Geraldion.\\n\\nThe second line contains n distinct space-separated numbers a1, a2, ..., an (1 ≤ ai ≤ 106) — the values of the banknotes.\', \'output_format\': \'Print a single line — the minimum unfortunate sum. If there are no unfortunate sums, print  - 1.\'}, \'56A\': {\'description\': "According to Berland laws it is only allowed to sell alcohol to people not younger than 18 years. Vasya\'s job is to monitor the law\'s enforcement. Tonight he entered a bar and saw n people sitting there. For every one of them Vasya happened to determine either the age or the drink the person is having. Vasya can check any person, i.e. learn his age and the drink he is having at the same time. What minimal number of people should Vasya check additionally to make sure that there are no clients under 18 having alcohol drinks?\\n\\nThe list of all alcohol drinks in Berland is: ABSINTH, BEER, BRANDY, CHAMPAGNE, GIN, RUM, SAKE, TEQUILA, VODKA, WHISKEY, WINE", \'id\': \'56/A\', \'input_format\': "The first line contains an integer n (1 ≤ n ≤ 100) which is the number of the bar\'s clients. Then follow n lines, each describing one visitor. A line either contains his age (an integer from 0 to 1000) or his drink (a string of capital Latin letters from 1 to 100 in length). It is guaranteed that the input data does not contain spaces and other unnecessary separators.\\n\\nOnly the drinks from the list given above should be considered alcohol.", \'output_format\': \'Print a single number which is the number of people Vasya should check to guarantee the law enforcement.\'}, \'579A\': {\'description\': \'You are a lover of bacteria. You want to raise some bacteria in a box.\\n\\nInitially, the box is empty. Each morning, you can put any number of bacteria into the box. And each night, every bacterium in the box will split into two bacteria. You hope to see exactly x bacteria in the box at some moment.\\n\\nWhat is the minimum number of bacteria you need to put into the box across those days?\', \'id\': \'579/A\', \'input_format\': \'The only line containing one integer x (1 ≤ x ≤ 109).\', \'output_format\': \'The only line containing one integer: the answer.\'}, \'583A\': {\'description\': \'City X consists of n vertical and n horizontal infinite roads, forming n × n intersections. Roads (both vertical and horizontal) are numbered from 1 to n, and the intersections are indicated by the numbers of the roads that form them.\\n\\nSand roads have long been recognized out of date, so the decision was made to asphalt them. To do this, a team of workers was hired and a schedule of work was made, according to which the intersections should be asphalted.\\n\\nRoad repairs are planned for n2 days. On the i-th day of the team arrives at the i-th intersection in the list and if none of the two roads that form the intersection were already asphalted they asphalt both roads. Otherwise, the team leaves the intersection, without doing anything with the roads.\\n\\nAccording to the schedule of road works tell in which days at least one road will be asphalted.\', \'id\': \'583/A\', \'input_format\': \'The first line contains integer n (1 ≤ n ≤ 50) — the number of vertical and horizontal roads in the city.\\n\\nNext n2 lines contain the order of intersections in the schedule. The i-th of them contains two numbers hi, vi (1 ≤ hi, vi ≤ n), separated by a space, and meaning that the intersection that goes i-th in the timetable is at the intersection of the hi-th horizontal and vi-th vertical roads. It is guaranteed that all the intersections in the timetable are distinct.\', \'output_format\': \'In the single line print the numbers of the days when road works will be in progress in ascending order. The days are numbered starting from 1.\'}, \'604A\': {\'description\': "Kevin Sun has just finished competing in Codeforces Round #334! The round was 120 minutes long and featured five problems with maximum point values of 500, 1000, 1500, 2000, and 2500, respectively. Despite the challenging tasks, Kevin was uncowed and bulldozed through all of them, distinguishing himself from the herd as the best cowmputer scientist in all of Bovinia. Kevin knows his submission time for each problem, the number of wrong submissions that he made on each problem, and his total numbers of successful and unsuccessful hacks. Because Codeforces scoring is complicated, Kevin wants you to write a program to compute his final score.\\n\\nCodeforces scores are computed as follows: If the maximum point value of a problem is x, and Kevin submitted correctly at minute m but made w wrong submissions, then his score on that problem is $$\\\\max \\\\left( 0.3x, \\\\left( 1 - \\\\frac{m}{250} \\\\right)x - 50w \\\\right)$$. His total score is equal to the sum of his scores for each problem. In addition, Kevin\'s total score gets increased by 100 points for each successful hack, but gets decreased by 50 points for each unsuccessful hack.\\n\\nAll arithmetic operations are performed with absolute precision and no rounding. It is guaranteed that Kevin\'s final score is an integer.", \'id\': \'604/A\', \'input_format\': "The first line of the input contains five space-separated integers m1, m2, m3, m4, m5, where mi (0 ≤ mi ≤ 119) is the time of Kevin\'s last submission for problem i. His last submission is always correct and gets accepted.\\n\\nThe second line contains five space-separated integers w1, w2, w3, w4, w5, where wi (0 ≤ wi ≤ 10) is Kevin\'s number of wrong submissions on problem i.\\n\\nThe last line contains two space-separated integers hs and hu (0 ≤ hs, hu ≤ 20), denoting the Kevin\'s numbers of successful and unsuccessful hacks, respectively.", \'output_format\': "Print a single integer, the value of Kevin\'s final score."}, \'608A\': {\'description\': \'Saitama accidentally destroyed a hotel again. To repay the hotel company, Genos has volunteered to operate an elevator in one of its other hotels. The elevator is special — it starts on the top floor, can only move down, and has infinite capacity. Floors are numbered from 0 to s and elevator initially starts on floor s at time 0.\\n\\nThe elevator takes exactly 1 second to move down exactly 1 floor and negligible time to pick up passengers. Genos is given a list detailing when and on which floor passengers arrive. Please determine how long in seconds it will take Genos to bring all passengers to floor 0.\', \'id\': \'608/A\', \'input_format\': \'The first line of input contains two integers n and s (1 ≤ n ≤ 100, 1 ≤ s ≤ 1000)\\xa0— the number of passengers and the number of the top floor respectively.\\n\\nThe next n lines each contain two space-separated integers fi and ti (1 ≤ fi ≤ s, 1 ≤ ti ≤ 1000)\\xa0— the floor and the time of arrival in seconds for the passenger number i.\', \'output_format\': \'Print a single integer\\xa0— the minimum amount of time in seconds needed to bring all the passengers to floor 0.\'}, \'610A\': {\'description\': "Pasha has a wooden stick of some positive integer length n. He wants to perform exactly three cuts to get four parts of the stick. Each part must have some positive integer length and the sum of these lengths will obviously be n.\\n\\nPasha likes rectangles but hates squares, so he wonders, how many ways are there to split a stick into four parts so that it\'s possible to form a rectangle using these parts, but is impossible to form a square.\\n\\nYour task is to help Pasha and count the number of such ways. Two ways to cut the stick are considered distinct if there exists some integer x, such that the number of parts of length x in the first way differ from the number of parts of length x in the second way.", \'id\': \'610/A\', \'input_format\': "The first line of the input contains a positive integer n (1 ≤ n ≤ 2·109) — the length of Pasha\'s stick.", \'output_format\': "The output should contain a single integer\\xa0— the number of ways to split Pasha\'s stick into four parts of positive integer length so that it\'s possible to make a rectangle by connecting the ends of these parts, but is impossible to form a square."}, \'616B\': {\'description\': "Jack decides to invite Emma out for a dinner. Jack is a modest student, he doesn\'t want to go to an expensive restaurant. Emma is a girl with high taste, she prefers elite places.\\n\\nMunhattan consists of n streets and m avenues. There is exactly one restaurant on the intersection of each street and avenue. The streets are numbered with integers from 1 to n and the avenues are numbered with integers from 1 to m. The cost of dinner in the restaurant at the intersection of the i-th street and the j-th avenue is cij.\\n\\nJack and Emma decide to choose the restaurant in the following way. Firstly Emma chooses the street to dinner and then Jack chooses the avenue. Emma and Jack makes their choice optimally: Emma wants to maximize the cost of the dinner, Jack wants to minimize it. Emma takes into account that Jack wants to minimize the cost of the dinner. Find the cost of the dinner for the couple in love.", \'id\': \'616/B\', \'input_format\': \'The first line contains two integers n, m (1 ≤ n, m ≤ 100) — the number of streets and avenues in Munhattan.\\n\\nEach of the next n lines contains m integers cij (1 ≤ cij ≤ 109) — the cost of the dinner in the restaurant on the intersection of the i-th street and the j-th avenue.\', \'output_format\': \'Print the only integer a — the cost of the dinner for Jack and Emma.\'}, \'620B\': {\'description\': "Once Max found an electronic calculator from his grandfather Dovlet\'s chest. He noticed that the numbers were written with seven-segment indicators (https://en.wikipedia.org/wiki/Seven-segment_display).\\n\\nMax starts to type all the values from a to b. After typing each number Max resets the calculator. Find the total number of segments printed on the calculator.\\n\\nFor example if a = 1 and b = 3 then at first the calculator will print 2 segments, then — 5 segments and at last it will print 5 segments. So the total number of printed segments is 12.", \'id\': \'620/B\', \'input_format\': \'The only line contains two integers a, b (1 ≤ a ≤ b ≤ 106) — the first and the last number typed by Max.\', \'output_format\': \'Print the only integer a — the total number of printed segments.\'}, \'628A\': {\'description\': "A tennis tournament with n participants is running. The participants are playing by an olympic system, so the winners move on and the losers drop out.\\n\\nThe tournament takes place in the following way (below, m is the number of the participants of the current round):\\n\\n- let k be the maximal power of the number 2 such that k\\u2009≤\\u2009m,\\n- k participants compete in the current round and a half of them passes to the next round, the other m\\u2009-\\u2009k participants pass to the next round directly,\\n- when only one participant remains, the tournament finishes.\\n\\nEach match requires b bottles of water for each participant and one bottle for the judge. Besides p towels are given to each participant for the whole tournament.\\n\\nFind the number of bottles and towels needed for the tournament.\\n\\nNote that it\'s a tennis tournament so in each match two participants compete (one of them will win and the other will lose).", \'id\': \'628/A\', \'input_format\': \'The only line contains three integers n, b, p (1 ≤ n, b, p ≤ 500) — the number of participants and the parameters described in the problem statement.\', \'output_format\': \'Print two integers x and y — the number of bottles and towels need for the tournament.\'}, \'637A\': {\'description\': \'After celebrating the midcourse the students of one of the faculties of the Berland State University decided to conduct a vote for the best photo. They published the photos in the social network and agreed on the rules to choose a winner: the photo which gets most likes wins. If multiple photoes get most likes, the winner is the photo that gets this number first.\\n\\nHelp guys determine the winner photo by the records of likes.\', \'id\': \'637/A\', \'input_format\': \'The first line of the input contains a single integer n (1 ≤ n ≤ 1000) — the total likes to the published photoes.\\n\\nThe second line contains n positive integers a1, a2, ..., an (1 ≤ ai ≤ 1 000 000), where ai is the identifier of the photo which got the i-th like.\', \'output_format\': \'Print the identifier of the photo which won the elections.\'}, \'641A\': {\'description\': \'Little Artem found a grasshopper. He brought it to his house and constructed a jumping area for him.\\n\\nThe area looks like a strip of cells 1 × n. Each cell contains the direction for the next jump and the length of that jump. Grasshopper starts in the first cell and follows the instructions written on the cells. Grasshopper stops immediately if it jumps out of the strip. Now Artem wants to find out if this will ever happen.\', \'id\': \'641/A\', \'input_format\': \'The first line of the input contains a single integer n (1 ≤ n ≤ 100 000)\\xa0— length of the strip.\\n\\nNext line contains a string of length n which consists of characters "<" and ">" only, that provide the direction of the jump from the corresponding cell. Next line contains n integers di (1 ≤ di ≤ 109)\\xa0— the length of the jump from the i-th cell.\', \'output_format\': \'Print "INFINITE" (without quotes) if grasshopper will continue his jumps forever. Otherwise print "FINITE" (without quotes).\'}, \'660B\': {\'description\': \'Consider 2n rows of the seats in a bus. n rows of the seats on the left and n rows of the seats on the right. Each row can be filled by two people. So the total capacity of the bus is 4n.\\n\\nConsider that m (m ≤ 4n) people occupy the seats in the bus. The passengers entering the bus are numbered from 1 to m (in the order of their entering the bus). The pattern of the seat occupation is as below:\\n\\n1-st row left window seat, 1-st row right window seat, 2-nd row left window seat, 2-nd row right window seat, ... , n-th row left window seat, n-th row right window seat.\\n\\nAfter occupying all the window seats (for m > 2n) the non-window seats are occupied:\\n\\n1-st row left non-window seat, 1-st row right non-window seat, ... , n-th row left non-window seat, n-th row right non-window seat.\\n\\nAll the passengers go to a single final destination. In the final destination, the passengers get off in the given order.\\n\\n1-st row left non-window seat, 1-st row left window seat, 1-st row right non-window seat, 1-st row right window seat, ... , n-th row left non-window seat, n-th row left window seat, n-th row right non-window seat, n-th row right window seat.\\n\\nThe seating for n = 9 and m = 36.\\n\\nYou are given the values n and m. Output m numbers from 1 to m, the order in which the passengers will get off the bus.\', \'id\': \'660/B\', \'input_format\': \'The only line contains two integers, n and m (1 ≤ n ≤ 100, 1 ≤ m ≤ 4n) — the number of pairs of rows and the number of passengers.\', \'output_format\': \'Print m distinct integers from 1 to m — the order in which the passengers will get off the bus.\'}, \'670B\': {\'description\': \'In late autumn evening n robots gathered in the cheerful company of friends. Each robot has a unique identifier\\xa0— an integer from 1 to 109.\\n\\nAt some moment, robots decided to play the game "Snowball". Below there are the rules of this game. First, all robots stand in a row. Then the first robot says his identifier. After that the second robot says the identifier of the first robot and then says his own identifier. Then the third robot says the identifier of the first robot, then says the identifier of the second robot and after that says his own. This process continues from left to right until the n-th robot says his identifier.\\n\\nYour task is to determine the k-th identifier to be pronounced.\', \'id\': \'670/B\', \'input_format\': \'The first line contains two positive integers n and k (1 ≤ n ≤ 100 000, 1 ≤ k ≤ min(2·109, n·(n + 1) / 2).\\n\\nThe second line contains the sequence id1, id2, ..., idn (1 ≤ idi ≤ 109)\\xa0— identifiers of roborts. It is guaranteed that all identifiers are different.\', \'output_format\': \'Print the k-th pronounced identifier (assume that the numeration starts from 1).\'}, \'672B\': {\'description\': \'A wise man told Kerem "Different is good" once, so Kerem wants all things in his life to be different.\\n\\nKerem recently got a string s consisting of lowercase English letters. Since Kerem likes it when things are different, he wants all substrings of his string s to be distinct. Substring is a string formed by some number of consecutive characters of the string. For example, string "aba" has substrings "" (empty substring), "a", "b", "a", "ab", "ba", "aba".\\n\\nIf string s has at least two equal substrings then Kerem will change characters at some positions to some other lowercase English letters. Changing characters is a very tiring job, so Kerem want to perform as few changes as possible.\\n\\nYour task is to find the minimum number of changes needed to make all the substrings of the given string distinct, or determine that it is impossible.\', \'id\': \'672/B\', \'input_format\': \'The first line of the input contains an integer n (1 ≤ n ≤ 100 000)\\xa0— the length of the string s.\\n\\nThe second line contains the string s of length n consisting of only lowercase English letters.\', \'output_format\': "If it\'s impossible to change the string s such that all its substring are distinct print -1. Otherwise print the minimum required number of changes."}, \'688B\': {\'description\': \'Pari has a friend who loves palindrome numbers. A palindrome number is a number that reads the same forward or backward. For example 12321, 100001 and 1 are palindrome numbers, while 112 and 1021 are not.\\n\\nPari is trying to love them too, but only very special and gifted people can understand the beauty behind palindrome numbers. Pari loves integers with even length (i.e. the numbers with even number of digits), so she tries to see a lot of big palindrome numbers with even length (like a 2-digit 11 or 6-digit 122221), so maybe she could see something in them.\\n\\nNow Pari asks you to write a program that gets a huge integer n from the input and tells what is the n-th even-length positive palindrome number?\', \'id\': \'688/B\', \'input_format\': \'The only line of the input contains a single integer n (1 ≤ n ≤ 10100 000).\', \'output_format\': \'Print the n-th even-length palindrome number.\'}, \'691A\': {\'description\': \'According to rules of the Berland fashion, a jacket should be fastened by all the buttons except only one, but not necessarily it should be the last one. Also if the jacket has only one button, it should be fastened, so the jacket will not swinging open.\\n\\nYou are given a jacket with n buttons. Determine if it is fastened in a right way.\', \'id\': \'691/A\', \'input_format\': \'The first line contains integer n (1 ≤ n ≤ 1000) — the number of buttons on the jacket.\\n\\nThe second line contains n integers ai (0 ≤ ai ≤ 1). The number ai = 0 if the i-th button is not fastened. Otherwise ai = 1.\', \'output_format\': \'In the only line print the word "YES" if the jacket is fastened in a right way. Otherwise print the word "NO".\'}, \'699A\': {\'description\': "There will be a launch of a new, powerful and unusual collider very soon, which located along a straight line. n particles will be launched inside it. All of them are located in a straight line and there can not be two or more particles located in the same point. The coordinates of the particles coincide with the distance in meters from the center of the collider, xi is the coordinate of the i-th particle and its position in the collider at the same time. All coordinates of particle positions are even integers.\\n\\nYou know the direction of each particle movement\\xa0— it will move to the right or to the left after the collider\'s launch start. All particles begin to move simultaneously at the time of the collider\'s launch start. Each particle will move straight to the left or straight to the right with the constant speed of 1 meter per microsecond. The collider is big enough so particles can not leave it in the foreseeable time.\\n\\nWrite the program which finds the moment of the first collision of any two particles of the collider. In other words, find the number of microseconds before the first moment when any two particles are at the same point.", \'id\': \'699/A\', \'input_format\': \'The first line contains the positive integer n (1 ≤ n ≤ 200 000)\\xa0— the number of particles.\\n\\nThe second line contains n symbols "L" and "R". If the i-th symbol equals "L", then the i-th particle will move to the left, otherwise the i-th symbol equals "R" and the i-th particle will move to the right.\\n\\nThe third line contains the sequence of pairwise distinct even integers x1, x2, ..., xn (0 ≤ xi ≤ 109)\\xa0— the coordinates of particles in the order from the left to the right. It is guaranteed that the coordinates of particles are given in the increasing order.\', \'output_format\': "In the first line print the only integer\\xa0— the first moment (in microseconds) when two particles are at the same point and there will be an explosion.\\n\\nPrint the only integer -1, if the collision of particles doesn\'t happen."}, \'69A\': {\'description\': \'A guy named Vasya attends the final grade of a high school. One day Vasya decided to watch a match of his favorite hockey team. And, as the boy loves hockey very much, even more than physics, he forgot to do the homework. Specifically, he forgot to complete his physics tasks. Next day the teacher got very angry at Vasya and decided to teach him a lesson. He gave the lazy student a seemingly easy task: You are given an idle body in space and the forces that affect it. The body can be considered as a material point with coordinates (0; 0; 0). Vasya had only to answer whether it is in equilibrium. "Piece of cake" — thought Vasya, we need only to check if the sum of all vectors is equal to 0. So, Vasya began to solve the problem. But later it turned out that there can be lots and lots of these forces, and Vasya can not cope without your help. Help him. Write a program that determines whether a body is idle or is moving by the given vectors of forces.\', \'id\': \'69/A\', \'input_format\': \'The first line contains a positive integer n (1 ≤ n ≤ 100), then follow n lines containing three integers each: the xi coordinate, the yi coordinate and the zi coordinate of the force vector, applied to the body ( - 100 ≤ xi, yi, zi ≤ 100).\', \'output_format\': \'Print the word "YES" if the body is in equilibrium, or the word "NO" if it is not.\'}, \'724A\': {\'description\': \'You are given names of two days of the week.\\n\\nPlease, determine whether it is possible that during some non-leap year the first day of some month was equal to the first day of the week you are given, while the first day of the next month was equal to the second day of the week you are given. Both months should belong to one year.\\n\\nIn this problem, we consider the Gregorian calendar to be used. The number of months in this calendar is equal to 12. The number of days in months during any non-leap year is: 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31.\\n\\nNames of the days of the week are given with lowercase English letters: "monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday".\', \'id\': \'724/A\', \'input_format\': \'The input consists of two lines, each of them containing the name of exactly one day of the week. It\\\'s guaranteed that each string in the input is from the set "monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday".\', \'output_format\': \'Print "YES" (without quotes) if such situation is possible during some non-leap year. Otherwise, print "NO" (without quotes).\'}, \'725A\': {\'description\': "In a new version of the famous Pinball game, one of the most important parts of the game field is a sequence of n bumpers. The bumpers are numbered with integers from 1 to n from left to right. There are two types of bumpers. They are denoted by the characters \'<\' and \'>\'. When the ball hits the bumper at position i it goes one position to the right (to the position i + 1) if the type of this bumper is \'>\', or one position to the left (to i - 1) if the type of the bumper at position i is \'<\'. If there is no such position, in other words if i - 1 < 1 or i + 1 > n, the ball falls from the game field.\\n\\nDepending on the ball\'s starting position, the ball may eventually fall from the game field or it may stay there forever. You are given a string representing the bumpers\' types. Calculate the number of positions such that the ball will eventually fall from the game field if it starts at that position.", \'id\': \'725/A\', \'input_format\': "The first line of the input contains a single integer n (1 ≤ n ≤ 200 000)\\xa0— the length of the sequence of bumpers. The second line contains the string, which consists of the characters \'<\' and \'>\'. The character at the i-th position of this string corresponds to the type of the i-th bumper.", \'output_format\': \'Print one integer\\xa0— the number of positions in the sequence such that the ball will eventually fall from the game field if it starts at that position.\'}, \'727A\': {\'description\': \'Vasily has a number a, which he wants to turn into a number b. For this purpose, he can do two types of operations:\\n\\n- multiply the current number by 2 (that is, replace the number x by 2·x);\\n- append the digit 1 to the right of current number (that is, replace the number x by 10·x\\u2009+\\u20091).\\n\\nYou need to help Vasily to transform the number a into the number b using only the operations described above, or find that it is impossible.\\n\\nNote that in this task you are not required to minimize the number of operations. It suffices to find any way to transform a into b.\', \'id\': \'727/A\', \'input_format\': \'The first line contains two positive integers a and b (1 ≤ a < b ≤ 109)\\xa0— the number which Vasily has and the number he wants to have.\', \'output_format\': \'If there is no way to get b from a, print "NO" (without quotes).\\n\\nOtherwise print three lines. On the first line print "YES" (without quotes). The second line should contain single integer k\\xa0— the length of the transformation sequence. On the third line print the sequence of transformations x1, x2, ..., xk, where:\\n\\n- x1 should be equal to a,\\n- xk should be equal to b,\\n- xi should be obtained from xi\\u2009-\\u20091 using any of two described operations (1\\u2009<\\u2009i\\u2009≤\\u2009k).\\n\\nIf there are multiple answers, print any of them.\'}, \'732B\': {\'description\': "Recently a dog was bought for Polycarp. The dog\'s name is Cormen. Now Polycarp has a lot of troubles. For example, Cormen likes going for a walk.\\n\\nEmpirically Polycarp learned that the dog needs at least k walks for any two consecutive days in order to feel good. For example, if k = 5 and yesterday Polycarp went for a walk with Cormen 2 times, today he has to go for a walk at least 3 times.\\n\\nPolycarp analysed all his affairs over the next n days and made a sequence of n integers a1, a2, ..., an, where ai is the number of times Polycarp will walk with the dog on the i-th day while doing all his affairs (for example, he has to go to a shop, throw out the trash, etc.).\\n\\nHelp Polycarp determine the minimum number of walks he needs to do additionaly in the next n days so that Cormen will feel good during all the n days. You can assume that on the day before the first day and on the day after the n-th day Polycarp will go for a walk with Cormen exactly k times.\\n\\nWrite a program that will find the minumum number of additional walks and the appropriate schedule\\xa0— the sequence of integers b1, b2, ..., bn (bi ≥ ai), where bi means the total number of walks with the dog on the i-th day.", \'id\': \'732/B\', \'input_format\': \'The first line contains two integers n and k (1 ≤ n, k ≤ 500)\\xa0— the number of days and the minimum number of walks with Cormen for any two consecutive days.\\n\\nThe second line contains integers a1, a2, ..., an (0 ≤ ai ≤ 500)\\xa0— the number of walks with Cormen on the i-th day which Polycarp has already planned.\', \'output_format\': \'In the first line print the smallest number of additional walks that Polycarp should do during the next n days so that Cormen will feel good during all days.\\n\\nIn the second line print n integers b1, b2, ..., bn, where bi\\xa0— the total number of walks on the i-th day according to the found solutions (ai ≤ bi for all i from 1 to n). If there are multiple solutions, print any of them.\'}, \'733A\': {\'description\': "One day, the Grasshopper was jumping on the lawn and found a piece of paper with a string. Grasshopper became interested what is the minimum jump ability he should have in order to be able to reach the far end of the string, jumping only on vowels of the English alphabet. Jump ability is the maximum possible length of his jump.\\n\\nFormally, consider that at the begginning the Grasshopper is located directly in front of the leftmost character of the string. His goal is to reach the position right after the rightmost character of the string. In one jump the Grasshopper could jump to the right any distance from 1 to the value of his jump ability.\\n\\nThe picture corresponds to the first example.\\n\\nThe following letters are vowels: \'A\', \'E\', \'I\', \'O\', \'U\' and \'Y\'.", \'id\': \'733/A\', \'input_format\': \'The first line contains non-empty string consisting of capital English letters. It is guaranteed that the length of the string does not exceed 100.\', \'output_format\': \'Print single integer a\\xa0— the minimum jump ability of the Grasshopper (in the number of symbols) that is needed to overcome the given string, jumping only on vowels.\'}, \'74A\': {\'description\': \'Let us remind you part of the rules of Codeforces. The given rules slightly simplified, use the problem statement as a formal document.\\n\\nIn the beginning of the round the contestants are divided into rooms. Each room contains exactly n participants. During the contest the participants are suggested to solve five problems, A, B, C, D and E. For each of these problem, depending on when the given problem was solved and whether it was solved at all, the participants receive some points. Besides, a contestant can perform hacks on other contestants. For each successful hack a contestant earns 100 points, for each unsuccessful hack a contestant loses 50 points. The number of points for every contestant is represented by the sum of points he has received from all his problems, including hacks.\\n\\nYou are suggested to determine the leader for some room; the leader is a participant who has maximum points.\', \'id\': \'74/A\', \'input_format\': \'The first line contains an integer n, which is the number of contestants in the room (1 ≤ n ≤ 50). The next n lines contain the participants of a given room. The i-th line has the format of "handlei plusi minusi ai bi ci di ei" — it is the handle of a contestant, the number of successful hacks, the number of unsuccessful hacks and the number of points he has received from problems A, B, C, D, E correspondingly. The handle of each participant consists of Latin letters, digits and underscores and has the length from 1 to 20 characters. There are the following limitations imposed upon the numbers:\\n\\n- 0\\u2009≤\\u2009plusi,\\u2009minusi\\u2009≤\\u200950;\\n- 150\\u2009≤\\u2009ai\\u2009≤\\u2009500 or ai\\u2009=\\u20090, if problem A is not solved;\\n- 300\\u2009≤\\u2009bi\\u2009≤\\u20091000 or bi\\u2009=\\u20090, if problem B is not solved;\\n- 450\\u2009≤\\u2009ci\\u2009≤\\u20091500 or ci\\u2009=\\u20090, if problem C is not solved;\\n- 600\\u2009≤\\u2009di\\u2009≤\\u20092000 or di\\u2009=\\u20090, if problem D is not solved;\\n- 750\\u2009≤\\u2009ei\\u2009≤\\u20092500 or ei\\u2009=\\u20090, if problem E is not solved.\\n\\nAll the numbers are integer. All the participants have different handles. It is guaranteed that there is exactly one leader in the room (i.e. there are no two participants with the maximal number of points).\', \'output_format\': \'Print on the single line the handle of the room leader.\'}, \'757A\': {\'description\': \'Bash wants to become a Pokemon master one day. Although he liked a lot of Pokemon, he has always been fascinated by Bulbasaur the most. Soon, things started getting serious and his fascination turned into an obsession. Since he is too young to go out and catch Bulbasaur, he came up with his own way of catching a Bulbasaur.\\n\\nEach day, he takes the front page of the newspaper. He cuts out the letters one at a time, from anywhere on the front page of the newspaper to form the word "Bulbasaur" (without quotes) and sticks it on his wall. Bash is very particular about case\\xa0— the first letter of "Bulbasaur" must be upper case and the rest must be lower case. By doing this he thinks he has caught one Bulbasaur. He then repeats this step on the left over part of the newspaper. He keeps doing this until it is not possible to form the word "Bulbasaur" from the newspaper.\\n\\nGiven the text on the front page of the newspaper, can you tell how many Bulbasaurs he will catch today?\\n\\nNote: uppercase and lowercase letters are considered different.\', \'id\': \'757/A\', \'input_format\': \'Input contains a single line containing a string s (1  ≤  |s|  ≤  105)\\xa0— the text on the front page of the newspaper without spaces and punctuation marks. |s| is the length of the string s.\\n\\nThe string s contains lowercase and uppercase English letters, i.e. $$s_i \\\\in \\\\{a,b,\\\\ldots,z,A,B,\\\\ldots,Z\\\\}$$.\', \'output_format\': \'Output a single integer, the answer to the problem.\'}, \'761A\': {\'description\': \'On her way to programming school tiger Dasha faced her first test — a huge staircase!\\n\\nThe steps were numbered from one to infinity. As we know, tigers are very fond of all striped things, it is possible that it has something to do with their color. So on some interval of her way she calculated two values — the number of steps with even and odd numbers.\\n\\nYou need to check whether there is an interval of steps from the l-th to the r-th (1 ≤ l ≤ r), for which values that Dasha has found are correct.\', \'id\': \'761/A\', \'input_format\': \'In the only line you are given two integers a, b (0 ≤ a, b ≤ 100) — the number of even and odd steps, accordingly.\', \'output_format\': \'In the only line print "YES", if the interval of steps described above exists, and "NO" otherwise.\'}, \'766B\': {\'description\': "Mahmoud has n line segments, the i-th of them has length ai. Ehab challenged him to use exactly 3 line segments to form a non-degenerate triangle. Mahmoud doesn\'t accept challenges unless he is sure he can win, so he asked you to tell him if he should accept the challenge. Given the lengths of the line segments, check if he can choose exactly 3 of them to form a non-degenerate triangle.\\n\\nMahmoud should use exactly 3 line segments, he can\'t concatenate two line segments or change any length. A non-degenerate triangle is a triangle with positive area.", \'id\': \'766/B\', \'input_format\': \'The first line contains single integer n (3 ≤ n ≤ 105)\\xa0— the number of line segments Mahmoud has.\\n\\nThe second line contains n integers a1, a2, ..., an (1 ≤ ai ≤ 109)\\xa0— the lengths of line segments Mahmoud has.\', \'output_format\': \'In the only line print "YES" if he can choose exactly three line segments and form a non-degenerate triangle with them, and "NO" otherwise.\'}, \'779A\': {\'description\': \'In Berland each high school student is characterized by academic performance — integer value between 1 and 5.\\n\\nIn high school 0xFF there are two groups of pupils: the group A and the group B. Each group consists of exactly n students. An academic performance of each student is known — integer value between 1 and 5.\\n\\nThe school director wants to redistribute students between groups so that each of the two groups has the same number of students whose academic performance is equal to 1, the same number of students whose academic performance is 2 and so on. In other words, the purpose of the school director is to change the composition of groups, so that for each value of academic performance the numbers of students in both groups are equal.\\n\\nTo achieve this, there is a plan to produce a series of exchanges of students between groups. During the single exchange the director selects one student from the class A and one student of class B. After that, they both change their groups.\\n\\nPrint the least number of exchanges, in order to achieve the desired equal numbers of students for each academic performance.\', \'id\': \'779/A\', \'input_format\': \'The first line of the input contains integer number n (1 ≤ n ≤ 100) — number of students in both groups.\\n\\nThe second line contains sequence of integer numbers a1, a2, ..., an (1 ≤ ai ≤ 5), where ai is academic performance of the i-th student of the group A.\\n\\nThe third line contains sequence of integer numbers b1, b2, ..., bn (1 ≤ bi ≤ 5), where bi is academic performance of the i-th student of the group B.\', \'output_format\': \'Print the required minimum number of exchanges or -1, if the desired distribution of students can not be obtained.\'}, \'798A\': {\'description\': \'Mike has a string s consisting of only lowercase English letters. He wants to change exactly one character from the string so that the resulting one is a palindrome.\\n\\nA palindrome is a string that reads the same backward as forward, for example strings "z", "aaa", "aba", "abccba" are palindromes, but strings "codeforces", "reality", "ab" are not.\', \'id\': \'798/A\', \'input_format\': \'The first and single line contains string s (1 ≤ |s| ≤ 15).\', \'output_format\': \'Print "YES" (without quotes) if Mike can change exactly one character so that the resulting string is palindrome or "NO" (without quotes) otherwise.\'}, \'804A\': {\'description\': \'A few years ago Sajjad left his school and register to another one due to security reasons. Now he wishes to find Amir, one of his schoolmates and good friends.\\n\\nThere are n schools numerated from 1 to n. One can travel between each pair of them, to do so, he needs to buy a ticket. The ticker between schools i and j costs $$(i+j) \\\\bmod (n+1)$$ and can be used multiple times. Help Sajjad to find the minimum cost he needs to pay for tickets to visit all schools. He can start and finish in any school.\', \'id\': \'804/A\', \'input_format\': \'The first line contains a single integer n (1 ≤ n ≤ 105)\\xa0— the number of schools.\', \'output_format\': \'Print single integer: the minimum cost of tickets needed to visit all schools.\'}, \'816A\': {\'description\': \'Karen is getting ready for a new school day!\\n\\nIt is currently hh:mm, given in a 24-hour format. As you know, Karen loves palindromes, and she believes that it is good luck to wake up when the time is a palindrome.\\n\\nWhat is the minimum number of minutes she should sleep, such that, when she wakes up, the time is a palindrome?\\n\\nRemember that a palindrome is a string that reads the same forwards and backwards. For instance, 05:39 is not a palindrome, because 05:39 backwards is 93:50. On the other hand, 05:50 is a palindrome, because 05:50 backwards is 05:50.\', \'id\': \'816/A\', \'input_format\': \'The first and only line of input contains a single string in the format hh:mm (00 ≤  hh  ≤ 23, 00 ≤  mm  ≤ 59).\', \'output_format\': \'Output a single integer on a line by itself, the minimum number of minutes she should sleep, such that, when she wakes up, the time is a palindrome.\'}, \'831A\': {\'description\': \'Array of integers is unimodal, if:\\n\\n- it is strictly increasing in the beginning;\\n- after that it is constant;\\n- after that it is strictly decreasing.\\n\\nThe first block (increasing) and the last block (decreasing) may be absent. It is allowed that both of this blocks are absent.\\n\\nFor example, the following three arrays are unimodal: [5, 7, 11, 11, 2, 1], [4, 4, 2], [7], but the following three are not unimodal: [5, 5, 6, 6, 1], [1, 2, 1, 2], [4, 5, 5, 6].\\n\\nWrite a program that checks if an array is unimodal.\', \'id\': \'831/A\', \'input_format\': \'The first line contains integer n (1 ≤ n ≤ 100) — the number of elements in the array.\\n\\nThe second line contains n integers a1, a2, ..., an (1 ≤ ai ≤ 1 000) — the elements of the array.\', \'output_format\': \'Print "YES" if the given array is unimodal. Otherwise, print "NO".\\n\\nYou can output each letter in any case (upper or lower).\'}, \'844A\': {\'description\': \'Calculate the minimum number of characters you need to change in the string s, so that it contains at least k different letters, or print that it is impossible.\\n\\nString s consists only of lowercase Latin letters, and it is allowed to change characters only to lowercase Latin letters too.\', \'id\': \'844/A\', \'input_format\': \'First line of input contains string s, consisting only of lowercase Latin letters (1 ≤ |s| ≤ 1000, |s| denotes the length of s).\\n\\nSecond line of input contains integer k (1 ≤ k ≤ 26).\', \'output_format\': \'Print single line with a minimum number of necessary changes, or the word «impossible» (without quotes) if it is impossible.\'}, \'847M\': {\'description\': "Vasya came up with his own weather forecasting method. He knows the information about the average air temperature for each of the last n days. Assume that the average air temperature for each day is integral.\\n\\nVasya believes that if the average temperatures over the last n days form an arithmetic progression, where the first term equals to the average temperature on the first day, the second term equals to the average temperature on the second day and so on, then the average temperature of the next (n + 1)-th day will be equal to the next term of the arithmetic progression. Otherwise, according to Vasya\'s method, the temperature of the (n + 1)-th day will be equal to the temperature of the n-th day.\\n\\nYour task is to help Vasya predict the average temperature for tomorrow, i. e. for the (n + 1)-th day.", \'id\': \'847/M\', \'input_format\': \'The first line contains a single integer n (2 ≤ n ≤ 100) — the number of days for which the average air temperature is known.\\n\\nThe second line contains a sequence of integers t1, t2, ..., tn ( - 1000 ≤ ti ≤ 1000)\\xa0— where ti is the average temperature in the i-th day.\', \'output_format\': \'Print the average air temperature in the (n + 1)-th day, which Vasya predicts according to his method. Note that the absolute value of the predicted temperature can exceed 1000.\'}, \'849A\': {\'description\': \'Where do odds begin, and where do they end? Where does hope emerge, and will they ever break?\\n\\nGiven an integer sequence a1, a2, ..., an of length n. Decide whether it is possible to divide it into an odd number of non-empty subsegments, the each of which has an odd length and begins and ends with odd numbers.\\n\\nA subsegment is a contiguous slice of the whole sequence. For example, {3, 4, 5} and {1} are subsegments of sequence {1, 2, 3, 4, 5, 6}, while {1, 2, 4} and {7} are not.\', \'id\': \'849/A\', \'input_format\': \'The first line of input contains a non-negative integer n (1 ≤ n ≤ 100) — the length of the sequence.\\n\\nThe second line contains n space-separated non-negative integers a1, a2, ..., an (0 ≤ ai ≤ 100) — the elements of the sequence.\', \'output_format\': \'Output "Yes" if it\\\'s possible to fulfill the requirements, and "No" otherwise.\\n\\nYou can output each letter in any case (upper or lower).\'}, \'862A\': {\'description\': "Dr. Evil kidnapped Mahmoud and Ehab in the evil land because of their performance in the Evil Olympiad in Informatics (EOI). He decided to give them some problems to let them go.\\n\\nDr. Evil is interested in sets, He has a set of n integers. Dr. Evil calls a set of integers evil if the MEX of it is exactly x. the MEX of a set of integers is the minimum non-negative integer that doesn\'t exist in it. For example, the MEX of the set {0, 2, 4} is 1 and the MEX of the set {1, 2, 3} is 0 .\\n\\nDr. Evil is going to make his set evil. To do this he can perform some operations. During each operation he can add some non-negative integer to his set or erase some element from it. What is the minimal number of operations Dr. Evil has to perform to make his set evil?", \'id\': \'862/A\', \'input_format\': \'The first line contains two integers n and x (1 ≤ n ≤ 100, 0 ≤ x ≤ 100)\\xa0— the size of the set Dr. Evil owns, and the desired MEX.\\n\\nThe second line contains n distinct non-negative integers not exceeding 100 that represent the set.\', \'output_format\': \'The only line should contain one integer\\xa0— the minimal number of operations Dr. Evil should perform.\'}, \'864A\': {\'description\': \'Petya and Vasya decided to play a game. They have n cards (n is an even number). A single integer is written on each card.\\n\\nBefore the game Petya will choose an integer and after that Vasya will choose another integer (different from the number that Petya chose). During the game each player takes all the cards with number he chose. For example, if Petya chose number 5 before the game he will take all cards on which 5 is written and if Vasya chose number 10 before the game he will take all cards on which 10 is written.\\n\\nThe game is considered fair if Petya and Vasya can take all n cards, and the number of cards each player gets is the same.\\n\\nDetermine whether Petya and Vasya can choose integer numbers before the game so that the game is fair.\', \'id\': \'864/A\', \'input_format\': \'The first line contains a single integer n (2 ≤ n ≤ 100) — number of cards. It is guaranteed that n is an even number.\\n\\nThe following n lines contain a sequence of integers a1, a2, ..., an (one integer per line, 1 ≤ ai ≤ 100) — numbers written on the n cards.\', \'output_format\': \'If it is impossible for Petya and Vasya to choose numbers in such a way that the game will be fair, print "NO" (without quotes) in the first line. In this case you should not print anything more.\\n\\nIn the other case print "YES" (without quotes) in the first line. In the second line print two distinct integers — number that Petya should choose and the number that Vasya should choose to make the game fair. If there are several solutions, print any of them.\'}, \'864B\': {\'description\': "Polycarp loves lowercase letters and dislikes uppercase ones. Once he got a string s consisting only of lowercase and uppercase Latin letters.\\n\\nLet A be a set of positions in the string. Let\'s call it pretty if following conditions are met:\\n\\n- letters on positions from A in the string are all distinct and lowercase;\\n- there are no uppercase letters in the string which are situated between positions from A (i.e. there is no such j that s[j] is an uppercase letter, and a1\\u2009<\\u2009j\\u2009<\\u2009a2 for some a1 and a2 from A).\\n\\nWrite a program that will determine the maximum number of elements in a pretty set of positions.", \'id\': \'864/B\', \'input_format\': \'The first line contains a single integer n (1 ≤ n ≤ 200) — length of string s.\\n\\nThe second line contains a string s consisting of lowercase and uppercase Latin letters.\', \'output_format\': \'Print maximum number of elements in pretty set of positions for string s.\'}, \'886A\': {\'description\': "In a small but very proud high school it was decided to win ACM ICPC. This goal requires to compose as many teams of three as possible, but since there were only 6 students who wished to participate, the decision was to build exactly two teams.\\n\\nAfter practice competition, participant number i got a score of ai. Team score is defined as sum of scores of its participants. High school management is interested if it\'s possible to build two teams with equal scores. Your task is to answer that question.", \'id\': \'886/A\', \'input_format\': \'The single line contains six integers a1, ..., a6 (0 ≤ ai ≤ 1000) — scores of the participants\', \'output_format\': \'Print "YES" (quotes for clarity), if it is possible to build teams with equal score, and "NO" otherwise.\\n\\nYou can print each character either upper- or lowercase ("YeS" and "yes" are valid when the answer is "YES").\'}, \'886B\': {\'description\': "Vlad likes to eat in cafes very much. During his life, he has visited cafes n times. Unfortunately, Vlad started to feel that his last visits are not any different from each other. To fix that Vlad had a small research.\\n\\nFirst of all, Vlad assigned individual indices to all cafes. Then, he wrote down indices of cafes he visited in a row, in order of visiting them. Now, Vlad wants to find such a cafe that his last visit to that cafe was before his last visits to every other cafe. In other words, he wants to find such a cafe that he hasn\'t been there for as long as possible. Help Vlad to find that cafe.", \'id\': \'886/B\', \'input_format\': \'In first line there is one integer n (1 ≤ n ≤ 2·105)\\xa0— number of cafes indices written by Vlad.\\n\\nIn second line, n numbers a1, a2, ..., an (0 ≤ ai ≤ 2·105) are written\\xa0— indices of cafes in order of being visited by Vlad. Vlad could visit some cafes more than once. Note that in numeration, some indices could be omitted.\', \'output_format\': "Print one integer\\xa0— index of the cafe that Vlad hasn\'t visited for as long as possible."}, \'887A\': {\'description\': "Top-model Izabella participates in the competition. She wants to impress judges and show her mathematical skills.\\n\\nHer problem is following: for given string, consisting of only 0 and 1, tell if it\'s possible to remove some digits in such a way, that remaining number is a representation of some positive integer, divisible by 64, in the binary numerical system.", \'id\': \'887/A\', \'input_format\': \'In the only line given a non-empty binary string s with length up to 100.\', \'output_format\': "Print «yes» (without quotes) if it\'s possible to remove digits required way and «no» otherwise."}, \'888B\': {\'description\': \'Ivan has a robot which is situated on an infinite grid. Initially the robot is standing in the starting cell (0, 0). The robot can process commands. There are four types of commands it can perform:\\n\\n- U — move from the cell (x,\\u2009y) to (x,\\u2009y\\u2009+\\u20091);\\n- D — move from (x,\\u2009y) to (x,\\u2009y\\u2009-\\u20091);\\n- L — move from (x,\\u2009y) to (x\\u2009-\\u20091,\\u2009y);\\n- R — move from (x,\\u2009y) to (x\\u2009+\\u20091,\\u2009y).\\n\\nIvan entered a sequence of n commands, and the robot processed it. After this sequence the robot ended up in the starting cell (0, 0), but Ivan doubts that the sequence is such that after performing it correctly the robot ends up in the same cell. He thinks that some commands were ignored by robot. To acknowledge whether the robot is severely bugged, he needs to calculate the maximum possible number of commands that were performed correctly. Help Ivan to do the calculations!\', \'id\': \'888/B\', \'input_format\': \'The first line contains one number n — the length of sequence of commands entered by Ivan (1 ≤ n ≤ 100).\\n\\nThe second line contains the sequence itself — a string consisting of n characters. Each character can be U, D, L or R.\', \'output_format\': \'Print the maximum possible number of commands from the sequence the robot could perform to end up in the starting cell.\'}, \'893B\': {\'description\': \'Recently Luba learned about a special kind of numbers that she calls beautiful numbers. The number is called beautiful iff its binary representation consists of k + 1 consecutive ones, and then k consecutive zeroes.\\n\\nSome examples of beautiful numbers:\\n\\n- 12 (110);\\n- 1102 (610);\\n- 11110002 (12010);\\n- 1111100002 (49610).\\n\\nMore formally, the number is beautiful iff there exists some positive integer k such that the number is equal to (2k - 1) * (2k - 1).\\n\\nLuba has got an integer number n, and she wants to find its greatest beautiful divisor. Help her to find it!\', \'id\': \'893/B\', \'input_format\': \'The only line of input contains one number n (1 ≤ n ≤ 105) — the number Luba has got.\', \'output_format\': "Output one number — the greatest beautiful divisor of Luba\'s number. It is obvious that the answer always exists."}, \'909A\': {\'description\': \'The preferred way to generate user login in Polygon is to concatenate a prefix of the user\\\'s first name and a prefix of their last name, in that order. Each prefix must be non-empty, and any of the prefixes can be the full name. Typically there are multiple possible logins for each person.\\n\\nYou are given the first and the last name of a user. Return the alphabetically earliest login they can get (regardless of other potential Polygon users).\\n\\nAs a reminder, a prefix of a string s is its substring which occurs at the beginning of s: "a", "ab", "abc" etc. are prefixes of string "{abcdef}" but "b" and \\\'bc" are not. A string a is alphabetically earlier than a string b, if a is a prefix of b, or a and b coincide up to some position, and then a has a letter that is alphabetically earlier than the corresponding letter in b: "a" and "ab" are alphabetically earlier than "ac" but "b" and "ba" are alphabetically later than "ac".\', \'id\': \'909/A\', \'input_format\': \'The input consists of a single line containing two space-separated strings: the first and the last names. Each character of each string is a lowercase English letter. The length of each string is between 1 and 10, inclusive.\', \'output_format\': \'Output a single string\\xa0— alphabetically earliest possible login formed from these names. The output should be given in lowercase as well.\'}, \'90A\': {\'description\': "A group of university students wants to get to the top of a mountain to have a picnic there. For that they decided to use a cableway.\\n\\nA cableway is represented by some cablecars, hanged onto some cable stations by a cable. A cable is scrolled cyclically between the first and the last cable stations (the first of them is located at the bottom of the mountain and the last one is located at the top). As the cable moves, the cablecar attached to it move as well.\\n\\nThe number of cablecars is divisible by three and they are painted three colors: red, green and blue, in such manner that after each red cablecar goes a green one, after each green cablecar goes a blue one and after each blue cablecar goes a red one. Each cablecar can transport no more than two people, the cablecars arrive with the periodicity of one minute (i. e. every minute) and it takes exactly 30 minutes for a cablecar to get to the top.\\n\\nAll students are divided into three groups: r of them like to ascend only in the red cablecars, g of them prefer only the green ones and b of them prefer only the blue ones. A student never gets on a cablecar painted a color that he doesn\'t like,\\n\\nThe first cablecar to arrive (at the moment of time 0) is painted red. Determine the least time it will take all students to ascend to the mountain top.", \'id\': \'90/A\', \'input_format\': \'The first line contains three integers r, g and b (0 ≤ r, g, b ≤ 100). It is guaranteed that r + g + b > 0, it means that the group consists of at least one student.\', \'output_format\': \'Print a single number — the minimal time the students need for the whole group to ascend to the top of the mountain.\'}, \'920A\': {\'description\': "It is winter now, and Max decided it\'s about time he watered the garden.\\n\\nThe garden can be represented as n consecutive garden beds, numbered from 1 to n. k beds contain water taps (i-th tap is located in the bed xi), which, if turned on, start delivering water to neighbouring beds. If the tap on the bed xi is turned on, then after one second has passed, the bed xi will be watered; after two seconds have passed, the beds from the segment [xi - 1, xi + 1] will be watered (if they exist); after j seconds have passed (j is an integer number), the beds from the segment [xi - (j - 1), xi + (j - 1)] will be watered (if they exist). Nothing changes during the seconds, so, for example, we can\'t say that the segment [xi - 2.5, xi + 2.5] will be watered after 2.5 seconds have passed; only the segment [xi - 2, xi + 2] will be watered at that moment.\\n\\nThe garden from test 1. White colour denotes a garden bed without a tap, red colour — a garden bed with a tap.\\n\\nThe garden from test 1 after 2 seconds have passed after turning on the tap. White colour denotes an unwatered garden bed, blue colour — a watered bed.\\n\\nMax wants to turn on all the water taps at the same moment, and now he wonders, what is the minimum number of seconds that have to pass after he turns on some taps until the whole garden is watered. Help him to find the answer!", \'id\': \'920/A\', \'input_format\': "The first line contains one integer t — the number of test cases to solve (1 ≤ t ≤ 200).\\n\\nThen t test cases follow. The first line of each test case contains two integers n and k (1 ≤ n ≤ 200, 1 ≤ k ≤ n) — the number of garden beds and water taps, respectively.\\n\\nNext line contains k integers xi (1 ≤ xi ≤ n) — the location of i-th water tap. It is guaranteed that for each $$i \\\\in [2;k]$$ condition xi - 1 < xi holds.\\n\\nIt is guaranteed that the sum of n over all test cases doesn\'t exceed 200.\\n\\nNote that in hacks you have to set t = 1.", \'output_format\': \'For each test case print one integer — the minimum number of seconds that have to pass after Max turns on some of the water taps, until the whole garden is watered.\'}, \'939B\': {\'description\': "Dima has a hamsters farm. Soon N hamsters will grow up on it and Dima will sell them in a city nearby.\\n\\nHamsters should be transported in boxes. If some box is not completely full, the hamsters in it are bored, that\'s why each box should be completely full with hamsters.\\n\\nDima can buy boxes at a factory. The factory produces boxes of K kinds, boxes of the i-th kind can contain in themselves ai hamsters. Dima can buy any amount of boxes, but he should buy boxes of only one kind to get a wholesale discount.\\n\\nOf course, Dima would buy boxes in such a way that each box can be completely filled with hamsters and transported to the city. If there is no place for some hamsters, Dima will leave them on the farm.\\n\\nFind out how many boxes and of which type should Dima buy to transport maximum number of hamsters.", \'id\': \'939/B\', \'input_format\': "The first line contains two integers N and K (0 ≤ N ≤ 1018, 1 ≤ K ≤ 105)\\xa0— the number of hamsters that will grow up on Dima\'s farm and the number of types of boxes that the factory produces.\\n\\nThe second line contains K integers a1, a2, ..., aK (1 ≤ ai ≤ 1018 for all i)\\xa0— the capacities of boxes.", \'output_format\': \'Output two integers: the type of boxes that Dima should buy and the number of boxes of that type Dima should buy. Types of boxes are numbered from 1 to K in the order they are given in input.\\n\\nIf there are many correct answers, output any of them.\'}, \'967B\': {\'description\': \'Arkady wants to water his only flower. Unfortunately, he has a very poor watering system that was designed for $$$n$$$ flowers and so it looks like a pipe with $$$n$$$ holes. Arkady can only use the water that flows from the first hole.\\n\\nArkady can block some of the holes, and then pour $$$A$$$ liters of water into the pipe. After that, the water will flow out from the non-blocked holes proportionally to their sizes $$$s_1, s_2, \\\\ldots, s_n$$$. In other words, if the sum of sizes of non-blocked holes is $$$S$$$, and the $$$i$$$-th hole is not blocked, $$$\\\\frac{s_i \\\\cdot A}{S}$$$ liters of water will flow out of it.\\n\\nWhat is the minimum number of holes Arkady should block to make at least $$$B$$$ liters of water flow out of the first hole?\', \'id\': \'967/B\', \'input_format\': \'The first line contains three integers $$$n$$$, $$$A$$$, $$$B$$$ ($$$1 \\\\le n \\\\le 100\\\\,000$$$, $$$1 \\\\le B \\\\le A \\\\le 10^4$$$)\\xa0— the number of holes, the volume of water Arkady will pour into the system, and the volume he wants to get out of the first hole.\\n\\nThe second line contains $$$n$$$ integers $$$s_1, s_2, \\\\ldots, s_n$$$ ($$$1 \\\\le s_i \\\\le 10^4$$$)\\xa0— the sizes of the holes.\', \'output_format\': \'Print a single integer\\xa0— the number of holes Arkady should block.\'}, \'978C\': {\'description\': \'There are $$$n$$$ dormitories in Berland State University, they are numbered with integers from $$$1$$$ to $$$n$$$. Each dormitory consists of rooms, there are $$$a_i$$$ rooms in $$$i$$$-th dormitory. The rooms in $$$i$$$-th dormitory are numbered from $$$1$$$ to $$$a_i$$$.\\n\\nA postman delivers letters. Sometimes there is no specific dormitory and room number in it on an envelope. Instead of it only a room number among all rooms of all $$$n$$$ dormitories is written on an envelope. In this case, assume that all the rooms are numbered from $$$1$$$ to $$$a_1 + a_2 + \\\\dots + a_n$$$ and the rooms of the first dormitory go first, the rooms of the second dormitory go after them and so on.\\n\\nFor example, in case $$$n=2$$$, $$$a_1=3$$$ and $$$a_2=5$$$ an envelope can have any integer from $$$1$$$ to $$$8$$$ written on it. If the number $$$7$$$ is written on an envelope, it means that the letter should be delivered to the room number $$$4$$$ of the second dormitory.\\n\\nFor each of $$$m$$$ letters by the room number among all $$$n$$$ dormitories, determine the particular dormitory and the room number in a dormitory where this letter should be delivered.\', \'id\': \'978/C\', \'input_format\': \'The first line contains two integers $$$n$$$ and $$$m$$$ $$$(1 \\\\le n, m \\\\le 2 \\\\cdot 10^{5})$$$ — the number of dormitories and the number of letters.\\n\\nThe second line contains a sequence $$$a_1, a_2, \\\\dots, a_n$$$ $$$(1 \\\\le a_i \\\\le 10^{10})$$$, where $$$a_i$$$ equals to the number of rooms in the $$$i$$$-th dormitory. The third line contains a sequence $$$b_1, b_2, \\\\dots, b_m$$$ $$$(1 \\\\le b_j \\\\le a_1 + a_2 + \\\\dots + a_n)$$$, where $$$b_j$$$ equals to the room number (among all rooms of all dormitories) for the $$$j$$$-th letter. All $$$b_j$$$ are given in increasing order.\', \'output_format\': \'Print $$$m$$$ lines. For each letter print two integers $$$f$$$ and $$$k$$$ — the dormitory number $$$f$$$ $$$(1 \\\\le f \\\\le n)$$$ and the room number $$$k$$$ in this dormitory $$$(1 \\\\le k \\\\le a_f)$$$ to deliver the letter.\'}, \'981B\': {\'description\': "Two famous competing companies ChemForces and TopChemist decided to show their sets of recently discovered chemical elements on an exhibition. However they know that no element should be present in the sets of both companies.\\n\\nIn order to avoid this representatives of both companies decided to make an agreement on the sets the companies should present. The sets should be chosen in the way that maximizes the total income of the companies.\\n\\nAll elements are enumerated with integers. The ChemForces company has discovered $$$n$$$ distinct chemical elements with indices $$$a_1, a_2, \\\\ldots, a_n$$$, and will get an income of $$$x_i$$$ Berland rubles if the $$$i$$$-th element from this list is in the set of this company.\\n\\nThe TopChemist company discovered $$$m$$$ distinct chemical elements with indices $$$b_1, b_2, \\\\ldots, b_m$$$, and it will get an income of $$$y_j$$$ Berland rubles for including the $$$j$$$-th element from this list to its set.\\n\\nIn other words, the first company can present any subset of elements from $$$\\\\{a_1, a_2, \\\\ldots, a_n\\\\}$$$ (possibly empty subset), the second company can present any subset of elements from $$$\\\\{b_1, b_2, \\\\ldots, b_m\\\\}$$$ (possibly empty subset). There shouldn\'t be equal elements in the subsets.\\n\\nHelp the representatives select the sets in such a way that no element is presented in both sets and the total income is the maximum possible.", \'id\': \'981/B\', \'input_format\': \'The first line contains a single integer $$$n$$$ ($$$1 \\\\leq n \\\\leq 10^5$$$) \\xa0— the number of elements discovered by ChemForces.\\n\\nThe $$$i$$$-th of the next $$$n$$$ lines contains two integers $$$a_i$$$ and $$$x_i$$$ ($$$1 \\\\leq a_i \\\\leq 10^9$$$, $$$1 \\\\leq x_i \\\\leq 10^9$$$) \\xa0— the index of the $$$i$$$-th element and the income of its usage on the exhibition. It is guaranteed that all $$$a_i$$$ are distinct.\\n\\nThe next line contains a single integer $$$m$$$ ($$$1 \\\\leq m \\\\leq 10^5$$$) \\xa0— the number of chemicals invented by TopChemist.\\n\\nThe $$$j$$$-th of the next $$$m$$$ lines contains two integers $$$b_j$$$ and $$$y_j$$$, ($$$1 \\\\leq b_j \\\\leq 10^9$$$, $$$1 \\\\leq y_j \\\\leq 10^9$$$) \\xa0— the index of the $$$j$$$-th element and the income of its usage on the exhibition. It is guaranteed that all $$$b_j$$$ are distinct.\', \'output_format\': \'Print the maximum total income you can obtain by choosing the sets for both companies in such a way that no element is presented in both sets.\'}, \'990A\': {\'description\': \'Berland Football Cup starts really soon! Commentators from all over the world come to the event.\\n\\nOrganizers have already built $$$n$$$ commentary boxes. $$$m$$$ regional delegations will come to the Cup. Every delegation should get the same number of the commentary boxes. If any box is left unoccupied then the delegations will be upset. So each box should be occupied by exactly one delegation.\\n\\nIf $$$n$$$ is not divisible by $$$m$$$, it is impossible to distribute the boxes to the delegations at the moment.\\n\\nOrganizers can build a new commentary box paying $$$a$$$ burles and demolish a commentary box paying $$$b$$$ burles. They can both build and demolish boxes arbitrary number of times (each time paying a corresponding fee). It is allowed to demolish all the existing boxes.\\n\\nWhat is the minimal amount of burles organizers should pay to satisfy all the delegations (i.e. to make the number of the boxes be divisible by $$$m$$$)?\', \'id\': \'990/A\', \'input_format\': \'The only line contains four integer numbers $$$n$$$, $$$m$$$, $$$a$$$ and $$$b$$$ ($$$1 \\\\le n, m \\\\le 10^{12}$$$, $$$1 \\\\le a, b \\\\le 100$$$), where $$$n$$$ is the initial number of the commentary boxes, $$$m$$$ is the number of delegations to come, $$$a$$$ is the fee to build a box and $$$b$$$ is the fee to demolish a box.\', \'output_format\': \'Output the minimal amount of burles organizers should pay to satisfy all the delegations (i.e. to make the number of the boxes be divisible by $$$m$$$). It is allowed that the final number of the boxes is equal to $$$0$$$.\'}, \'991A\': {\'description\': "Each student eagerly awaits the day he would pass the exams successfully. Thus, Vasya was ready to celebrate, but, alas, he didn\'t pass it. However, many of Vasya\'s fellow students from the same group were more successful and celebrated after the exam.\\n\\nSome of them celebrated in the BugDonalds restaurant, some of them\\xa0— in the BeaverKing restaurant, the most successful ones were fast enough to celebrate in both of restaurants. Students which didn\'t pass the exam didn\'t celebrate in any of those restaurants and elected to stay home to prepare for their reexamination. However, this quickly bored Vasya and he started checking celebration photos on the Kilogramm. He found out that, in total, BugDonalds was visited by $$$A$$$ students, BeaverKing\\xa0— by $$$B$$$ students and $$$C$$$ students visited both restaurants. Vasya also knows that there are $$$N$$$ students in his group.\\n\\nBased on this info, Vasya wants to determine either if his data contradicts itself or, if it doesn\'t, how many students in his group didn\'t pass the exam. Can you help him so he won\'t waste his valuable preparation time?", \'id\': \'991/A\', \'input_format\': \'The first line contains four integers\\xa0— $$$A$$$, $$$B$$$, $$$C$$$ and $$$N$$$ ($$$0 \\\\leq A, B, C, N \\\\leq 100$$$).\', \'output_format\': "If a distribution of $$$N$$$ students exists in which $$$A$$$ students visited BugDonalds, $$$B$$$ — BeaverKing, $$$C$$$ — both of the restaurants and at least one student is left home (it is known that Vasya didn\'t pass the exam and stayed at home), output one integer\\xa0— amount of students (including Vasya) who did not pass the exam.\\n\\nIf such a distribution does not exist and Vasya made a mistake while determining the numbers $$$A$$$, $$$B$$$, $$$C$$$ or $$$N$$$ (as in samples 2 and 3), output $$$-1$$$."}}\nRULES = {pid: REVIEW[pid]["input_format"] + " Unique output; deterministic authored oracle below implements the retained problem description." for pid in IDS}\nNUMERIC = {\n    "1A": ((1,10**9),)*3, "13A": ((3,1000),), "90A": ((0,100),)*3,\n    "109A": ((1,10**6),), "118B": ((2,9),), "122A": ((1,1000),),\n    "195A": ((2,1000),(1,999),(1,1000)), "268B": ((1,2000),),\n    "379A": ((1,1000),(2,1000)), "535A": ((0,99),), "579A": ((1,10**9),),\n    "610A": ((1,2*10**9),), "620B": ((1,10**6),)*2, "628A": ((1,500),)*3,\n    "660B": ((1,100),(1,400)), "761A": ((0,100),)*2, "804A": ((1,10**5),),\n    "886A": ((0,1000),)*6, "893B": ((1,10**5),),\n    "990A": ((1,10**12),(1,10**12),(1,100),(1,100)), "991A": ((0,100),)*4,\n}\n\n\ndef token(word, pattern, low, high):\n    if not low <= len(word) <= high or not re.fullmatch(pattern, word):\n        raise ValueError("invalid string domain")\n    return word\n\n\ndef require(condition):\n    if not condition:\n        raise ValueError("invalid dependent constraint")\n\n\ndef array(values, n, low, high):\n    require(len(values) == n)\n    for v in values:\n        within(v,low,high)\n    return values\n\n\ndef yn(condition):\n    return "YES\\n" if condition else "NO\\n"\n\n\ndef numeric(pid, v):\n    require(len(v) == len(NUMERIC[pid]))\n    for x,(lo,hi) in zip(v,NUMERIC[pid]):\n        within(x,lo,hi)\n    if pid == "1A":\n        n,m,a = v\n        return (n+a-1)//a*((m+a-1)//a)\n    if pid == "13A":\n        a, = v\n        total = 0\n        for base in range(2,a):\n            x = a\n            while x:\n                total += x % base\n                x //= base\n        divisor = math.gcd(total,a-2)\n        return f"{total//divisor}/{(a-2)//divisor}"\n    if pid == "90A":\n        require(sum(v)>0)\n        return max(30+i+3*((count-1)//2) for i,count in enumerate(v) if count)\n    if pid == "109A":\n        n, = v\n        for sevens in range(n//7,-1,-1):\n            rest = n-7*sevens\n            if rest % 4 == 0:\n                return "4"*(rest//4)+"7"*sevens\n        return -1\n    if pid == "118B":\n        n, = v\n        lines = []\n        for h in list(range(n+1))+list(range(n-1,-1,-1)):\n            values = list(range(h+1))+list(range(h-1,-1,-1))\n            lines.append(" "*(2*(n-h))+" ".join(map(str,values)))\n        return "\\n".join(lines)\n    if pid == "122A":\n        n, = v\n        lucky = [int("".join(s)) for length in range(1,4) for s in itertools.product("47",repeat=length)]\n        return "YES" if any(n%x==0 for x in lucky) else "NO"\n    if pid == "195A":\n        a,b,c = v\n        require(a>b)\n        return (c*(a-b)+b-1)//b\n    if pid == "268B":\n        n, = v\n        return n+sum((n-known)*known for known in range(1,n))\n    if pid == "379A":\n        a,b = v\n        answer,stubs = a,a\n        while stubs>=b:\n            new,rem = divmod(stubs,b)\n            answer += new\n            stubs = new+rem\n        return answer\n    if pid == "535A":\n        n, = v\n        first = "zero one two three four five six seven eight nine ten eleven twelve thirteen fourteen fifteen sixteen seventeen eighteen nineteen".split()\n        tens = "twenty thirty forty fifty sixty seventy eighty ninety".split()\n        return first[n] if n<20 else tens[n//10-2]+("-"+first[n%10] if n%10 else "")\n    if pid == "579A":\n        return v[0].bit_count()\n    if pid == "610A":\n        n, = v\n        return 0 if n%2 else max(0,(n//2-1)//2)\n    if pid == "620B":\n        a,b = v\n        require(a<=b)\n        prefix = segment_prefix()\n        return prefix[b]-prefix[a-1]\n    if pid == "628A":\n        n,b,p = v\n        return f"{(n-1)*(2*b+1)} {n*p}"\n    if pid == "660B":\n        n,m = v\n        require(m<=4*n)\n        return " ".join(str(x) for i in range(1,2*n+1) for x in (i+2*n,i) if x<=m)\n    if pid == "761A":\n        a,b = v\n        return "YES" if a+b>0 and abs(a-b)<=1 else "NO"\n    if pid == "804A":\n        return (v[0]-1)//2\n    if pid == "886A":\n        return "YES" if any(2*sum(c)==sum(v) for c in itertools.combinations(v,3)) else "NO"\n    if pid == "893B":\n        n, = v\n        return max((2**k-1)*2**(k-1) for k in range(1,10) if n%((2**k-1)*2**(k-1))==0)\n    if pid == "990A":\n        n,m,a,b = v\n        rem = n%m\n        return min(rem*b,(m-rem)*a) if rem else 0\n    if pid == "991A":\n        a,b,c,n = v\n        absent = n-(a+b-c)\n        return absent if c<=min(a,b) and absent>=1 else -1\n    raise ValueError("unimplemented numeric problem")\n\n\n@lru_cache(maxsize=1)\ndef segment_prefix():\n    from array import array as int_array\n    counts = (6,2,5,5,4,5,6,3,7,6)\n    prefix = int_array("I",[0])\n    for i in range(1,10**6+1):\n        prefix.append(prefix[-1]+sum(counts[int(x)] for x in str(i)))\n    return prefix\n\n\ndef output(pid,text):\n    if pid in NUMERIC:\n        return str(numeric(pid,integers(text)))+"\\n"\n    words = text.split()\n    if pid == "106A":\n        require(len(words)==3 and words[0] in "SHDC" and len(words[0])==1)\n        trump,a,b = words\n        token(a,r"[6789TJQKA][SHDC]",2,2)\n        token(b,r"[6789TJQKA][SHDC]",2,2)\n        require(a!=b)\n        return yn((a[1]==b[1] and "6789TJQKA".index(a[0])>"6789TJQKA".index(b[0])) or (a[1]!=b[1] and a[1]==trump))\n    if pid in ("118A","122B","733A","798A","887A"):\n        require(len(words)==1)\n        s = words[0]\n        spec = {"118A":(r"[A-Za-z]+",100),"122B":(r"[0-9]+",50),"733A":(r"[A-Z]+",100),"798A":(r"[a-z]+",15),"887A":(r"[01]+",100)}\n        pattern,limit = spec[pid]\n        token(s,pattern,1,limit)\n        if pid == "118A":\n            s = s.lower()\n            require(any(x not in "aoyeui" for x in s))\n            return "".join("."+x for x in s if x not in "aoyeui")+"\\n"\n        if pid == "122B":\n            a,b = s.count("4"),s.count("7")\n            return ("-1" if not a+b else "4" if a>=b else "7")+"\\n"\n        if pid == "733A":\n            points = [0]+[i+1 for i,c in enumerate(s) if c in "AEIOUY"]+[len(s)+1]\n            return str(max(b-a for a,b in zip(points,points[1:])))+"\\n"\n        if pid == "798A":\n            mismatches = sum(s[i]!=s[-i-1] for i in range(len(s)//2))\n            return yn(mismatches==1 or (mismatches==0 and len(s)%2==1))\n        if pid == "887A":\n            return yn("1" in s and s[s.index("1")+1:].count("0")>=6)\n    if pid == "259A":\n        require(len(words)==8)\n        for row in words:\n            token(row,r"[WB]+",8,8)\n        return yn(all(all(a!=b for a,b in zip(row,row[1:])) for row in words))\n    if pid == "724A":\n        days = "monday tuesday wednesday thursday friday saturday sunday".split()\n        require(len(words)==2 and all(s in days for s in words))\n        return yn((days.index(words[1])-days.index(words[0]))%7 in (0,2,3))\n    if pid == "816A":\n        require(len(words)==1)\n        token(words[0],r"[0-9]{2}:[0-9]{2}",5,5)\n        h,m = map(int,words[0].split(":"))\n        within(h,0,23)\n        within(m,0,59)\n        for wait in range(1440):\n            now = (h*60+m+wait)%1440\n            s = f"{now//60:02}:{now%60:02}"\n            if s==s[::-1]:\n                return str(wait)+"\\n"\n    if pid == "909A":\n        require(len(words)==2)\n        a,b = words\n        token(a,r"[a-z]+",1,10)\n        token(b,r"[a-z]+",1,10)\n        return min(a[:i]+b[:j] for i in range(1,len(a)+1) for j in range(1,len(b)+1))+"\\n"\n    if pid in ("864B","888B"):\n        require(len(words)==2 and words[0].isdigit())\n        n = int(words[0])\n        within(n,1,200 if pid=="864B" else 100)\n        s = token(words[1],r"[A-Za-z]+" if pid=="864B" else r"[UDLR]+",n,n)\n        if pid == "864B":\n            return str(max(map(lambda w:len(set(w)),re.split("[A-Z]",s))))+"\\n"\n        return str(2*(min(s.count("U"),s.count("D"))+min(s.count("L"),s.count("R"))))+"\\n"\n    v = integers(text)\n    if pid == "604A":\n        require(len(v)==12)\n        array(v[:5],5,0,119)\n        array(v[5:10],5,0,10)\n        array(v[10:],2,0,20)\n        score = sum(max(150*i,500*i-2*i*m-50*w) for i,(m,w) in enumerate(zip(v[:5],v[5:10]),1))\n        return str(score+100*v[10]-50*v[11])+"\\n"\n    if pid in ("272A","368A","371A","385A","435A"):\n        require(len(v)>=2)\n        n,parameter = v[:2]\n        within(n,2 if pid=="385A" else 1,100)\n        if pid == "272A":\n            needs = array(v[1:],n,1,5)\n            return str(sum((sum(needs)+x)%(n+1)!=1 for x in range(1,6)))+"\\n"\n        if pid == "368A":\n            within(parameter,1,100)\n            require(len(v)==n+3)\n            prices = array(v[2:-1],n,1,100)\n            m = v[-1]\n            within(m,1,100)\n            return str(sum(sorted(prices)[:m])-max(0,m-n)*parameter)+"\\n"\n        if pid == "371A":\n            within(parameter,1,n)\n            require(n%parameter==0)\n            a = array(v[2:],n,1,2)\n            return str(sum(min(a[i::parameter].count(1),a[i::parameter].count(2)) for i in range(parameter)))+"\\n"\n        if pid == "385A":\n            within(parameter,0,100)\n            a = array(v[2:],n,0,100)\n            return str(max([0]+[a[i]-a[i+1]-parameter for i in range(n-1)]))+"\\n"\n        within(parameter,1,100)\n        a = array(v[2:],n,1,parameter)\n        buses,load = 1,0\n        for x in a:\n            if load+x>parameter:\n                buses,load = buses+1,0\n            load += x\n        return str(buses)+"\\n"\n    if pid in ("389A","779A","831A","847M","849A","862A"):\n        n = v[0]\n        within(n,2 if pid in ("389A","847M") else 1,100)\n        if pid == "862A":\n            require(len(v)==n+2)\n            x = v[1]\n            within(x,0,100)\n            a = array(v[2:],n,0,100)\n            require(len(set(a))==n)\n            return str(sum(i not in a for i in range(x))+(x in a))+"\\n"\n        if pid == "779A":\n            require(len(v)==2*n+1)\n            a = array(v[1:n+1],n,1,5)\n            b = array(v[n+1:],n,1,5)\n            ca,cb = Counter(a),Counter(b)\n            if any((ca[i]+cb[i])%2 for i in range(1,6)):\n                return "-1\\n"\n            return str(sum(abs(ca[i]-cb[i]) for i in range(1,6))//4)+"\\n"\n        a = array(v[1:],n,-1000 if pid=="847M" else 0 if pid=="849A" else 1,1000 if pid in ("847M","831A") else 100)\n        if pid == "389A":\n            return str(n*math.gcd(*a))+"\\n"\n        if pid == "847M":\n            d = a[1]-a[0]\n            return str(a[-1]+(d if all(y-x==d for x,y in zip(a,a[1:])) else 0))+"\\n"\n        if pid == "849A":\n            return yn(n%2==1 and a[0]%2==1 and a[-1]%2==1)\n        phase = 0\n        for x,y in zip(a,a[1:]):\n            if y>x:\n                if phase:\n                    return "NO\\n"\n            elif y==x:\n                if phase==2:\n                    return "NO\\n"\n                phase = 1\n            else:\n                phase = 2\n        return "YES\\n"\n    raise ValueError("unimplemented reviewed problem")\n\n\ndef flat(*values):\n    return " ".join(map(str,values))+"\\n"\n\n\ndef inputs(pid):\n    rng = random.Random("1000-reviewed-v1-"+pid)\n    small,maximum = [],[]\n    if pid in NUMERIC:\n        bounds = NUMERIC[pid]\n        candidates = list(itertools.product(*[(lo,hi) for lo,hi in bounds]))\n        candidates += [tuple(rng.randint(lo,hi) for lo,hi in bounds) for _ in range(60)]\n        if len(bounds)==1:\n            candidates += [(i,) for i in range(bounds[0][0],min(bounds[0][1]+1,32))]\n        for v in candidates:\n            if pid=="90A" and not sum(v):\n                continue\n            if pid=="195A" and v[0]<=v[1]:\n                continue\n            if pid=="620B" and v[0]>v[1]:\n                v = tuple(sorted(v))\n            if pid=="660B" and v[1]>4*v[0]:\n                continue\n            small.append(flat(*v))\n        maximum = [s for s in small if any(int(x)==hi for x,(_,hi) in zip(s.split(),bounds))]\n        return small,maximum\n    if pid=="106A":\n        cards = [a+b for a in "6789TJQKA" for b in "SHDC"]\n        small = [flat(trump,a,b) for trump in "SHDC" for a,b in [rng.sample(cards,2) for _ in range(40)]]\n        maximum = [flat("S","AS","6H"),flat("S","6S","AS")]\n    elif pid in ("118A","122B","733A","798A","887A"):\n        alphabet,limit = {"118A":("aAoeUiYbBcCdDzZ",100),"122B":("0123456789",50),"733A":("ABCDEFYIOU",100),"798A":("abc",15),"887A":("01",100)}[pid]\n        small = [rng.choice(alphabet)+"\\n" for _ in range(10)]\n        small += ["".join(rng.choice(alphabet) for _ in range(rng.randint(1,limit)))+"\\n" for _ in range(60)]\n        maximum = [c*limit+"\\n" for c in alphabet]\n        if pid=="118A":\n            small = [s for s in small if any(x not in "aoyeui" for x in s.strip().lower())]\n            maximum = [s for s in maximum if any(x not in "aoyeui" for x in s.strip().lower())]\n        if pid=="887A":\n            small += ["0\\n","1\\n","1000000\\n","01000000\\n","100000\\n","1010101010101\\n"]\n        if pid=="798A":\n            small += ["a\\n","aa\\n","ab\\n","abc\\n","aba\\n","abca\\n","abcde\\n"]\n    elif pid=="259A":\n        small = ["\\n".join(rng.choice(["WB"*4,"BW"*4]) for _ in range(8))+"\\n" for _ in range(60)]\n        small += ["\\n".join("".join(rng.choice("WB") for _ in range(8)) for _ in range(8))+"\\n" for _ in range(20)]\n        maximum = ["\\n".join(["W"*8]*8)+"\\n","\\n".join(["WB"*4]*8)+"\\n"]\n    elif pid=="724A":\n        days = "monday tuesday wednesday thursday friday saturday sunday".split()\n        small = [flat(a,b) for a in days for b in days]\n        maximum = [flat("sunday","sunday")]\n    elif pid=="816A":\n        small = [f"{h:02}:{m:02}\\n" for h in range(24) for m in (0,1,9,10,11,22,32,33,44,55,58,59)]\n        maximum = ["23:59\\n","23:32\\n"]\n    elif pid=="909A":\n        small = [flat(a,b) for a in ("a","ab","aba","bac","zz") for b in ("a","b","ba","z")]\n        small += [flat(*( "".join(rng.choice("abcxyz") for _ in range(rng.randint(1,10))) for _ in range(2))) for _ in range(60)]\n        maximum = [flat("z"*10,"a"*10),flat("a"*10,"z"*10)]\n    elif pid in ("864B","888B"):\n        alphabet,limit = ("abczABCZ",200) if pid=="864B" else ("UDLR",100)\n        small = [flat(n,"".join(rng.choice(alphabet) for _ in range(n))) for n in range(1,61)]\n        maximum = [flat(limit,c*limit) for c in alphabet]\n        maximum += [flat(limit,(alphabet*((limit+len(alphabet)-1)//len(alphabet)))[:limit])]\n    elif pid=="604A":\n        small = [flat(*(rng.randint(0,119) for _ in range(5)),*(rng.randint(0,10) for _ in range(5)),rng.randint(0,20),rng.randint(0,20)) for _ in range(60)]\n        maximum = [flat(*([119]*5+[10]*5+[20,20])),flat(*([0]*10+[20,0])),flat(*([119]*5+[10]*5+[0,20]))]\n    else:\n        for rep in range(60):\n            n = rng.randint(2 if pid in ("385A","389A","847M") else 1,100)\n            small.append(array_input(pid,n,rep,rng))\n        maximum = [array_input(pid,100,mode,rng) for mode in (-1,-2,-3)]\n    require(bool(small) and bool(maximum))\n    return small+maximum,maximum\n\n\ndef array_input(pid,n,mode,rng):\n    def values(low,high):\n        return ([low]*n if mode==-1 else [high]*n if mode==-2 else [low if i%2 else high for i in range(n)] if mode==-3 else [rng.randint(low,high) for _ in range(n)])\n    if pid=="272A":\n        return flat(n,*values(1,5))\n    if pid=="368A":\n        return flat(n,100 if mode<0 else rng.randint(1,100),*values(1,100),100 if mode<0 else rng.randint(1,100))\n    if pid=="371A":\n        k = 1 if mode==-1 else n if mode==-2 else rng.choice([i for i in range(1,n+1) if n%i==0])\n        return flat(n,k,*values(1,2))\n    if pid=="385A":\n        return flat(n,100 if mode==-1 else 0 if mode<0 else rng.randint(0,100),*values(0,100))\n    if pid=="435A":\n        m = 100 if mode<0 else rng.randint(1,100)\n        return flat(n,m,*values(1,m))\n    if pid=="389A":\n        return flat(n,*values(1,100))\n    if pid=="779A":\n        a = values(1,5)\n        b = a[:] if mode==-1 else list(reversed(a)) if mode==-2 else values(1,5)\n        return flat(n,*a,*b)\n    if pid=="831A":\n        return flat(n,*values(1,1000))\n    if pid=="847M":\n        return flat(n,*values(-1000,1000))\n    if pid=="849A":\n        return flat(n,*values(0,100))\n    if pid=="862A":\n        a = rng.sample(range(101),n)\n        return flat(n,100 if mode<0 else rng.randint(0,100),*a)\n    raise ValueError("unimplemented array generator")\n\n\ndef extras(pid):\n    cases,maximum = inputs(pid)\n    seen = set()\n    result = []\n    for s in cases:\n        if s not in seen:\n            result.append({"input":layout(pid,s),"output":output(pid,s),"caseKind":"max-size" if s in maximum else "boundary-adversarial"})\n            seen.add(s)\n    return result\n', 'generated_recipes': '"""Generated-basis candidates; independent oracle/audit deliberately not fabricated."""\nfrom collections import Counter\nfrom bisect import bisect_left\nimport itertools\nimport random\n\nfrom additional import REVIEW, array, flat, require, token, yn\nfrom recipes import integers, within\n\nIDS = tuple("29A 37A 69A 102B 127B 137B 165A 230A 237A 265B 284B 299A 339B 352A 359A 400A 404A 441A 447B 462A 465B 499A 499B 500A 560A 583A 608A 616B 641A 688B 691A 766B 886B 920A 967B 978C 981B 1008B".split())\nRULES = {p: REVIEW[p]["input_format"]+" Unique token result under retained description; generated qualification and independent oracle/audit outstanding." for p in IDS}\n\n\ndef big_number(s,allow_zero):\n    token(s,r"[0-9]+",1,100001)\n    require((s=="0" and allow_zero) or (s[0]!="0" and (len(s)<=100000 or s=="1"+"0"*100000)))\n    return s\n\n\ndef read_grid(v,n,m,low,high):\n    array(v,n*m,low,high)\n    return [v[i*m:(i+1)*m] for i in range(n)]\n\n\ndef output(pid,text):\n    words = text.split()\n    if pid in ("102B","688B"):\n        require(len(words)==1)\n        s = big_number(words[0],pid=="102B")\n        if pid=="688B":\n            return s+s[::-1]+"\\n"\n        operations = 0\n        while len(s)>1:\n            s = str(sum(map(int,s)))\n            operations += 1\n        return str(operations)+"\\n"\n    if pid in ("284B","404A","462A","641A","447B","400A","499B"):\n        return string_output(pid,words)\n    v = integers(text)\n    if pid in ("37A","127B","137B","265B","299A","352A","465B","560A","691A","766B","886B"):\n        n = v[0]\n        limits = {"37A":(1,1000,1,1000),"127B":(1,100,1,100),"137B":(1,5000,1,5000),\n                  "265B":(1,10**5,1,10**4),"299A":(1,10**5,1,10**9),"352A":(1,1000,0,5),\n                  "465B":(1,1000,0,1),"560A":(1,1000,1,10**6),"691A":(1,1000,0,1),\n                  "766B":(3,10**5,1,10**9),"886B":(1,2*10**5,0,2*10**5)}\n        lo,hi,alo,ahi = limits[pid]\n        within(n,lo,hi)\n        a = array(v[1:],n,alo,ahi)\n        if pid=="265B":\n            require(len(text.splitlines())==n+1 and all(len(row.split())==1 for row in text.splitlines()))\n        counts = Counter(a)\n        if pid=="37A":\n            return f"{max(counts.values())} {len(counts)}\\n"\n        if pid=="127B":\n            return str(sum(c//2 for c in counts.values())//2)+"\\n"\n        if pid=="137B":\n            return str(n-len(set(x for x in a if x<=n)))+"\\n"\n        if pid=="265B":\n            return str(a[0]+sum(abs(x-y) for x,y in zip(a,a[1:]))+2*n-1)+"\\n"\n        if pid=="299A":\n            divisor = min(a)\n            return str(divisor if all(x%divisor==0 for x in a) else -1)+"\\n"\n        if pid=="352A":\n            require(all(x in (0,5) for x in a))\n            if not counts[0]:\n                return "-1\\n"\n            fives = counts[5]//9*9\n            return ("5"*fives+"0"*counts[0] if fives else "0")+"\\n"\n        if pid=="465B":\n            positions = [i for i,x in enumerate(a) if x]\n            return str(0 if not positions else 1+sum(min(y-x,2) for x,y in zip(positions,positions[1:])))+"\\n"\n        if pid=="560A":\n            require(len(counts)==n)\n            return "-1\\n" if 1 in counts else "1\\n"\n        if pid=="691A":\n            return yn(a[0]==1 if n==1 else counts[0]==1)\n        if pid=="766B":\n            a = sorted(a)\n            return yn(any(a[i]+a[i+1]>a[i+2] for i in range(n-2)))\n        last = {x:i for i,x in enumerate(a)}\n        return str(min(last,key=last.get))+"\\n"\n    if pid in ("29A","69A","165A","237A","1008B"):\n        n = v[0]\n        size = 3 if pid=="69A" else 2\n        limit = 200 if pid=="165A" else 10**5 if pid in ("237A","1008B") else 100\n        within(n,1,limit)\n        require(len(v)==1+n*size)\n        records = [v[1+i*size:1+(i+1)*size] for i in range(n)]\n        if pid=="29A":\n            for x,d in records:\n                within(x,-10**4,10**4)\n                within(abs(d),1,2*10**4)\n            require(len({x for x,d in records})==n)\n            spit = dict(records)\n            return yn(any(x+d in spit and spit[x+d]==-d for x,d in records))\n        if pid=="69A":\n            array(v[1:],n*3,-100,100)\n            return yn(all(sum(r[k] for r in records)==0 for k in range(3)))\n        if pid=="165A":\n            array(v[1:],n*2,-1000,1000)\n            require(len(set(map(tuple,records)))==n)\n            vertical,horizontal = {},{}\n            for x,y in records:\n                vertical.setdefault(x,[]).append(y)\n                horizontal.setdefault(y,[]).append(x)\n            count = sum(min(vertical[x])<y<max(vertical[x]) and min(horizontal[y])<x<max(horizontal[y]) for x,y in records)\n            return str(count)+"\\n"\n        if pid=="237A":\n            for h,m in records:\n                within(h,0,23)\n                within(m,0,59)\n            times = [60*h+m for h,m in records]\n            require(times==sorted(times))\n            return str(max(Counter(times).values()))+"\\n"\n        height = 10**9\n        for w,h in records:\n            within(w,1,10**9)\n            within(h,1,10**9)\n            choices = [x for x in (w,h) if x<=height]\n            if not choices:\n                return "NO\\n"\n            height = max(choices)\n        return "YES\\n"\n    if pid in ("230A","339B","500A","608A","499A"):\n        require(len(v)>=2)\n        first,n = v[:2]\n        if pid=="230A":\n            strength = first\n            within(strength,1,10**4)\n            within(n,1,1000)\n            require(len(v)==2+2*n)\n            dragons = [tuple(v[2+i*2:4+i*2]) for i in range(n)]\n            for x,y in dragons:\n                within(x,1,10**4)\n                within(y,0,10**4)\n            for x,y in sorted(dragons):\n                if strength<=x:\n                    return "NO\\n"\n                strength += y\n            return "YES\\n"\n        if pid=="339B":\n            houses,tasks = first,n\n            within(houses,2,10**5)\n            within(tasks,1,10**5)\n            a = array(v[2:],tasks,1,houses)\n            current,total = 1,0\n            for target in a:\n                total += (target-current)%houses\n                current = target\n            return str(total)+"\\n"\n        if pid=="500A":\n            cells,target = first,n\n            within(cells,3,30000)\n            within(target,2,cells)\n            require(len(v)==cells+1)\n            jumps = v[2:]\n            for i,x in enumerate(jumps,1):\n                within(x,1,cells-i)\n            current = 1\n            while current<target:\n                current += jumps[current-1]\n            return yn(current==target)\n        if pid=="608A":\n            passengers,top = first,n\n            within(passengers,1,100)\n            within(top,1,1000)\n            require(len(v)==2+2*passengers)\n            records = [v[2+i*2:4+i*2] for i in range(passengers)]\n            for floor,time in records:\n                within(floor,1,top)\n                within(time,1,1000)\n            return str(max([top]+[floor+time for floor,time in records]))+"\\n"\n        moments,skip = first,n\n        within(moments,1,50)\n        within(skip,1,10**5)\n        require(len(v)==2+2*moments)\n        intervals = [v[2+i*2:4+i*2] for i in range(moments)]\n        current,watch = 1,0\n        for left,right in intervals:\n            within(left,current,10**5)\n            within(right,left,10**5)\n            current += (left-current)//skip*skip\n            watch += right-current+1\n            current = right+1\n        return str(watch)+"\\n"\n    if pid in ("359A","616B"):\n        require(len(v)>=2)\n        n,m = v[:2]\n        within(n,3 if pid=="359A" else 1,50 if pid=="359A" else 100)\n        within(m,3 if pid=="359A" else 1,50 if pid=="359A" else 100)\n        grid = read_grid(v[2:],n,m,0 if pid=="359A" else 1,1 if pid=="359A" else 10**9)\n        if pid=="616B":\n            return str(max(map(min,grid)))+"\\n"\n        require(sum(map(sum,grid))>0 and all(grid[i][j]==0 for i in (0,n-1) for j in (0,m-1)))\n        edge = any(grid[i][j] for i in range(n) for j in range(m) if i in (0,n-1) or j in (0,m-1))\n        return "2\\n" if edge else "4\\n"\n    if pid=="441A":\n        n,budget = v[:2]\n        within(n,1,50)\n        within(budget,10**4,10**6)\n        offset,buy = 2,[]\n        for seller in range(1,n+1):\n            require(offset<len(v))\n            k = v[offset]\n            within(k,1,50)\n            prices = array(v[offset+1:offset+1+k],k,10**4,10**6)\n            if min(prices)<budget:\n                buy.append(seller)\n            offset += k+1\n        require(offset==len(v))\n        return str(len(buy))+"\\n"+" ".join(map(str,buy))+"\\n"\n    if pid=="583A":\n        n = v[0]\n        within(n,1,50)\n        require(len(v)==1+2*n*n)\n        pairs = [tuple(v[1+i*2:3+i*2]) for i in range(n*n)]\n        require(len(set(pairs))==n*n)\n        used_h,used_v,days = set(),set(),[]\n        for day,(h,w) in enumerate(pairs,1):\n            within(h,1,n)\n            within(w,1,n)\n            if h not in used_h and w not in used_v:\n                used_h.add(h)\n                used_v.add(w)\n                days.append(day)\n        return " ".join(map(str,days))+"\\n"\n    if pid=="920A":\n        t = v[0]\n        within(t,1,200)\n        offset,total,answers = 1,0,[]\n        for _ in range(t):\n            require(offset+2<=len(v))\n            n,k = v[offset:offset+2]\n            within(n,1,200)\n            within(k,1,n)\n            taps = array(v[offset+2:offset+2+k],k,1,n)\n            require(taps==sorted(set(taps)))\n            total += n\n            answers.append(max(min(abs(i-x) for x in taps) for i in range(1,n+1))+1)\n            offset += 2+k\n        require(offset==len(v) and total<=200)\n        return "\\n".join(map(str,answers))+"\\n"\n    if pid=="967B":\n        n,a,b = v[:3]\n        within(n,1,10**5)\n        within(a,1,10**4)\n        within(b,1,a)\n        sizes = array(v[3:],n,1,10**4)\n        total,blocked = sum(sizes),0\n        for size in sorted(sizes[1:],reverse=True):\n            if total*b<=a*sizes[0]:\n                break\n            total -= size\n            blocked += 1\n        return str(blocked)+"\\n"\n    if pid=="978C":\n        n,m = v[:2]\n        within(n,1,2*10**5)\n        within(m,1,2*10**5)\n        require(len(v)==2+n+m)\n        rooms = array(v[2:2+n],n,1,10**10)\n        cumulative = list(itertools.accumulate(rooms))\n        queries = array(v[2+n:],m,1,cumulative[-1])\n        require(queries==sorted(set(queries)))\n        answers = []\n        for q in queries:\n            i = bisect_left(cumulative,q)\n            answers.append(f"{i+1} {q-(cumulative[i-1] if i else 0)}")\n        return "\\n".join(answers)+"\\n"\n    if pid=="981B":\n        offset,incomes = 0,{}\n        for _ in range(2):\n            require(offset<len(v))\n            n = v[offset]\n            within(n,1,10**5)\n            require(offset+1+2*n<=len(v))\n            seen = set()\n            for i in range(n):\n                idx,profit = v[offset+1+2*i:offset+3+2*i]\n                within(idx,1,10**9)\n                within(profit,1,10**9)\n                require(idx not in seen)\n                seen.add(idx)\n                incomes[idx] = max(incomes.get(idx,0),profit)\n            offset += 1+2*n\n        require(offset==len(v))\n        return str(sum(incomes.values()))+"\\n"\n    raise ValueError("unknown generated-basis recipe")\n\n\ndef string_output(pid,words):\n    if pid=="447B":\n        require(len(words)==28)\n        s = token(words[0],r"[a-z]+",1,1000)\n        k = int(words[1])\n        within(k,0,1000)\n        weights = array(integers(" ".join(words[2:])),26,0,1000)\n        result = sum((i+1)*weights[ord(c)-97] for i,c in enumerate(s))\n        result += max(weights)*k*(2*len(s)+k+1)//2\n        return str(result)+"\\n"\n    if pid=="499B":\n        require(len(words)>=2)\n        n,m = map(int,words[:2])\n        within(n,1,3000)\n        within(m,1,3000)\n        require(len(words)==2+2*m+n)\n        first,second,mapping = set(),set(),{}\n        for i in range(m):\n            a,b = words[2+2*i:4+2*i]\n            token(a,r"[a-z]+",1,10)\n            token(b,r"[a-z]+",1,10)\n            require(a not in first and b not in second)\n            first.add(a)\n            second.add(b)\n            mapping[a] = a if len(a)<=len(b) else b\n        require(not first.intersection(second))\n        lecture = words[2+2*m:]\n        require(all(c in mapping for c in lecture))\n        return " ".join(mapping[c] for c in lecture)+"\\n"\n    require(words and words[0].isdigit())\n    n = int(words[0])\n    if pid=="400A":\n        within(n,1,100)\n        require(len(words)==n+1)\n        answers = []\n        for s in words[1:]:\n            token(s,r"[XO]+",12,12)\n            choices = [f"{a}x{12//a}" for a in (1,2,3,4,6,12) if any(all(s[row*(12//a)+col]=="X" for row in range(a)) for col in range(12//a))]\n            answers.append(str(len(choices))+(" "+" ".join(choices) if choices else ""))\n        return "\\n".join(answers)+"\\n"\n    if pid=="284B":\n        within(n,2,2*10**5)\n        require(len(words)==2)\n        s = token(words[1],r"[AIF]+",n,n)\n        ins = s.count("I")\n        return str(s.count("A") if ins==0 else 1 if ins==1 else 0)+"\\n"\n    if pid=="641A":\n        within(n,1,10**5)\n        require(len(words)==n+2)\n        directions = token(words[1],r"[<>]+",n,n)\n        distances = array(integers(" ".join(words[2:])),n,1,10**9)\n        current,seen = 0,set()\n        while 0<=current<n and current not in seen:\n            seen.add(current)\n            current += distances[current]*(1 if directions[current]==">" else -1)\n        return "INFINITE\\n" if current in seen else "FINITE\\n"\n    within(n,3 if pid=="404A" else 1,299 if pid=="404A" else 100)\n    require(len(words)==n+1)\n    grid = words[1:]\n    for row in grid:\n        token(row,r"[a-z]+" if pid=="404A" else r"[xo]+",n,n)\n    if pid=="404A":\n        require(n%2==1)\n        diagonal,background = grid[0][0],grid[0][1]\n        return yn(diagonal!=background and all(grid[i][j]==(diagonal if i==j or i+j==n-1 else background) for i in range(n) for j in range(n)))\n    return yn(all(sum(grid[x][y]=="o" for x,y in ((i-1,j),(i+1,j),(i,j-1),(i,j+1)) if 0<=x<n and 0<=y<n)%2==0 for i in range(n) for j in range(n)))\n\n\ndef lines(*rows):\n    return "".join(flat(*row) if isinstance(row,(list,tuple)) else str(row)+"\\n" for row in rows)\n\n\ndef values(n,lo,hi,mode,rng):\n    return [lo if mode==-1 else hi if mode==-2 else lo if i%2 else hi if mode==-3 else rng.randint(lo,hi) for i in range(n)]\n\n\ndef make_input(pid,rng,mode):\n    maximum = mode<0\n    limits = {"37A":1000,"127B":100,"137B":5000,"265B":10**5,"299A":10**5,"352A":1000,\n              "465B":1000,"560A":1000,"691A":1000,"766B":10**5,"886B":2*10**5}\n    if pid in limits:\n        n = limits[pid] if maximum else rng.randint(3 if pid=="766B" else 1,20)\n        domains = {"37A":(1,1000),"127B":(1,100),"137B":(1,5000),"265B":(1,10**4),"299A":(1,10**9),"352A":(0,1),"465B":(0,1),"560A":(1,10**6),"691A":(0,1),"766B":(1,10**9),"886B":(0,2*10**5)}\n        lo,hi = domains[pid]\n        a = values(n,lo,hi,mode,rng)\n        if pid=="352A":\n            a = [5*x for x in a]\n        if pid=="560A":\n            a = list(range(1,n+1)) if mode==-1 else list(range(10**6-n+1,10**6+1)) if mode==-2 else rng.sample(range(1,10**6+1),n)\n        return lines(n,*a) if pid=="265B" else lines(n,a)\n    if pid in ("102B","688B"):\n        s = "1"+"0"*100000 if mode==-1 else "9"*100000 if mode==-2 else "1"+"01"*49999 if mode==-3 else str(rng.randint(0 if pid=="102B" else 1,10**9))\n        return s+"\\n"\n    if pid in ("29A","69A","165A","237A","1008B"):\n        limit = 200 if pid=="165A" else 10**5 if pid in ("237A","1008B") else 100\n        n = limit if maximum else rng.randint(1,15)\n        if pid=="29A":\n            positions = rng.sample(range(-10**4,10**4+1),n)\n            records = [(x,rng.choice([-1,1])*rng.randint(1,2*10**4)) for x in positions]\n            if n>=2 and mode%2==0:\n                records[0] = (positions[0],positions[1]-positions[0])\n                records[1] = (positions[1],positions[0]-positions[1])\n        elif pid=="69A":\n            records = [values(3,-100,100,mode,rng) for _ in range(n)]\n            if mode==-3:\n                records = [[100,-100,0] if i%2 else [-100,100,0] for i in range(n)]\n        elif pid=="165A":\n            universe = [(x,y) for x in range(-20,21) for y in range(-20,21)]\n            records = rng.sample(universe,n)\n            if mode==-1:\n                records = [(i-100,1000) for i in range(n)]\n            if mode==-2:\n                records = [(1000,i-100) for i in range(n)]\n        elif pid=="237A":\n            times = sorted(values(n,0,1439,mode,rng))\n            records = [divmod(t,60) for t in times]\n        else:\n            records = [values(2,1,10**9,mode,rng) for _ in range(n)]\n            if mode==-3:\n                records = [(10**9-i,1+i) for i in range(n)]\n        return lines(n,*records)\n    if pid=="230A":\n        n = 1000 if maximum else rng.randint(1,12)\n        strength = 1 if mode==-1 else 10000 if mode==-2 else rng.randint(1,10000)\n        dragons = [(rng.randint(1,10000),rng.randint(0,10000)) for _ in range(n)]\n        if mode==-1:\n            dragons = [(1,0)]*n\n        if mode==-2:\n            dragons = [(9999,10000)]*n\n        return lines((strength,n),*dragons)\n    if pid=="339B":\n        n,m = (10**5,10**5) if maximum else (rng.randint(2,20),rng.randint(1,20))\n        return lines((n,m),values(m,1,n,mode,rng))\n    if pid=="284B":\n        n = 2*10**5 if maximum else rng.randint(2,20)\n        s = "A"*n if mode==-1 else "I"*n if mode==-2 else "I"+"A"*(n-1) if mode==-3 else "".join(rng.choice("AIF") for _ in range(n))\n        return lines(n,s)\n    if pid in ("359A","616B"):\n        hi,lo = (50,3) if pid=="359A" else (100,1)\n        n,m = (hi,hi) if maximum else (rng.randint(lo,8),rng.randint(lo,8))\n        grid = [values(m,0 if pid=="359A" else 1,1 if pid=="359A" else 10**9,mode,rng) for _ in range(n)]\n        if pid=="359A":\n            for i in (0,n-1):\n                for j in (0,m-1):\n                    grid[i][j] = 0\n            if mode==-1:\n                grid[1][1] = 1\n            if not any(map(any,grid)):\n                grid[0][1] = 1\n        return lines((n,m),*grid)\n    if pid=="400A":\n        t = 100 if maximum else rng.randint(1,12)\n        rows = ["X"*12 if mode==-1 else "O"*12 if mode==-2 else "XO"*6 if mode==-3 else "".join(rng.choice("XO") for _ in range(12)) for _ in range(t)]\n        return lines(t,*rows)\n    if pid in ("404A","462A"):\n        n = 299 if pid=="404A" and maximum else 100 if maximum else rng.choice([3,5,7,9]) if pid=="404A" else rng.randint(1,8)\n        if pid=="404A":\n            diagonal,background = rng.sample("abcdefghijklmnopqrstuvwxyz",2)\n            grid = ["".join(diagonal if i==j or i+j==n-1 else background for j in range(n)) for i in range(n)]\n            if mode%2==0:\n                grid[0] = background+grid[0][1:]\n        else:\n            grid = ["x"*n if mode==-1 else "o"*n if mode==-2 else "".join(rng.choice("xo") for _ in range(n)) for _ in range(n)]\n        return lines(n,*grid)\n    if pid=="441A":\n        n = 50 if maximum else rng.randint(1,8)\n        budget = 10**4 if mode==-1 else 10**6 if mode==-2 else rng.randint(10**4,10**6)\n        sellers = []\n        for _ in range(n):\n            k = 50 if maximum else rng.randint(1,8)\n            sellers.append([k]+values(k,10**4,10**6,mode,rng))\n        return lines((n,budget),*sellers)\n    if pid=="447B":\n        n,k = (1000,1000) if maximum else (rng.randint(1,20),rng.randint(0,20))\n        s = "z"*n if mode==-1 else "a"*n if mode==-2 else "".join(rng.choice("abcdefghijklmnopqrstuvwxyz") for _ in range(n))\n        return lines(s,k,values(26,0,1000,mode,rng))\n    if pid=="499A":\n        n = 50 if maximum else rng.randint(1,12)\n        x = 10**5 if mode==-1 else 1 if mode==-2 else rng.randint(1,100)\n        intervals,current = [],1\n        for _ in range(n):\n            left = current+rng.randint(0,20)\n            right = left+rng.randint(0,20)\n            intervals.append((left,right))\n            current = right+1\n        if maximum:\n            intervals[-1] = (99999,100000)\n        return lines((n,x),*intervals)\n    if pid=="499B":\n        n,m = (3000,3000) if maximum else (rng.randint(1,20),rng.randint(1,20))\n        def encode(i):\n            s = ""\n            while i:\n                i,r = divmod(i,26)\n                s += chr(97+r)\n            return s or "a"\n        pairs = [("a"+encode(i),"z"+encode(i)+("zz" if i%2 else "")) for i in range(m)]\n        return lines((n,m),*pairs,[rng.choice(pairs)[0] for _ in range(n)])\n    if pid=="500A":\n        n = 30000 if maximum else rng.randint(3,25)\n        target = n if maximum else rng.randint(2,n)\n        jumps = [1 if mode==-1 else n-i if mode==-2 else rng.randint(1,n-i) for i in range(1,n)]\n        return lines((n,target),jumps)\n    if pid=="583A":\n        n = 50 if maximum else rng.randint(1,10)\n        schedule = [(h,w) for h in range(1,n+1) for w in range(1,n+1)]\n        if mode==-2:\n            schedule.reverse()\n        elif mode!=-1:\n            rng.shuffle(schedule)\n        return lines(n,*schedule)\n    if pid=="608A":\n        n,s = (100,1000) if maximum else (rng.randint(1,12),rng.randint(1,30))\n        records = [(1 if mode==-1 else s if mode==-2 else rng.randint(1,s),1000 if maximum else rng.randint(1,100)) for _ in range(n)]\n        return lines((n,s),*records)\n    if pid=="641A":\n        n = 10**5 if maximum else rng.randint(1,25)\n        directions = "<"*n if mode==-1 else "><"+">"*(n-2) if mode==-2 else "".join(rng.choice("<>") for _ in range(n))\n        distances = [1]*n if mode==-2 else values(n,1,10**9,mode,rng)\n        return lines(n,directions,distances)\n    if pid=="920A":\n        if mode==-3:\n            return lines(200,*[row for _ in range(200) for row in ((1,1),(1,))])\n        n = 200 if maximum else rng.randint(1,20)\n        taps = [1] if mode==-1 else [200] if mode==-2 else list(range(1,201)) if mode==-3 else sorted(rng.sample(range(1,n+1),rng.randint(1,n)))\n        return lines(1,(n,len(taps)),taps)\n    if pid=="967B":\n        n = 10**5 if maximum else rng.randint(1,20)\n        a = 10000 if maximum else rng.randint(1,20)\n        b = a if mode==-1 else 1 if mode==-2 else rng.randint(1,a)\n        return lines((n,a,b),values(n,1,10000,mode,rng))\n    if pid=="978C":\n        n,m = (2*10**5,2*10**5) if maximum else (rng.randint(1,15),rng.randint(1,15))\n        if mode==-2:\n            m = 1\n        if mode==-3:\n            n,m = 1,1\n        rooms = [1 if mode==-1 else 10**10]*n if maximum else [rng.randint(1,30) for _ in range(n)]\n        m = min(m,sum(rooms))\n        queries = list(range(1,m+1)) if mode==-1 else list(range(sum(rooms)-m+1,sum(rooms)+1)) if mode==-2 else sorted(rng.sample(range(1,sum(rooms)+1),m))\n        return lines((n,m),rooms,queries)\n    if pid=="981B":\n        n,m = (10**5,10**5) if maximum else (rng.randint(1,12),rng.randint(1,12))\n        if mode==-3:\n            return lines(1,(10**9,10**9),1,(10**9,1))\n        first = [(i+1,1 if mode==-1 else 10**9 if maximum else rng.randint(1,100)) for i in range(n)]\n        second = [(i+1+(10**8 if mode==-2 else 0),1 if mode==-1 else 10**9 if maximum else rng.randint(1,100)) for i in range(m)]\n        return lines(n,*first,m,*second)\n    raise ValueError("unimplemented generated input")\n\n\ndef extras(pid):\n    rng = random.Random("1000-generated-v1-"+pid)\n    seen,result = set(),[]\n    for mode in [-1,-2,-3]+list(range(180)):\n        text = make_input(pid,rng,mode)\n        if text in seen:\n            continue\n        seen.add(text)\n        result.append({"input":text,"output":output(pid,text),"caseKind":"max-size" if mode<0 else "boundary-adversarial"})\n    return result\n', 'replenish': '"""Statement-reviewed replenishment; no independent audit signoff implied."""\nfrom collections import Counter\nimport math\nimport random\n\nfrom additional import REVIEW,array,require,token,yn\nfrom generated_recipes import lines,values\nfrom recipes import integers,within\n\nIDS = tuple("336A 727A 14B 43A 56A 74A 106B 182B 637A 670B 672B 699A 725A 757A 844A".split())\nRULES = {p:REVIEW[p]["input_format"]+" Unique result under retained statement; 727A inverse operations have disjoint parity and determine one path. Independent audit required." for p in IDS}\nDRINKS = "ABSINTH BEER BRANDY CHAMPAGNE GIN RUM SAKE TEQUILA VODKA WHISKEY WINE".split()\n\n\ndef output(pid,text):\n    w = text.split()\n    require(bool(w))\n    if pid in ("43A","56A","74A","672B","699A","725A","757A","844A"):\n        return string_output(pid,w)\n    v = integers(text)\n    if pid=="336A":\n        require(len(v)==2)\n        x,y = v\n        within(x,-10**9,10**9)\n        within(y,-10**9,10**9)\n        require(x!=0 and y!=0)\n        distance = abs(x)+abs(y)\n        points = sorted([(distance if x>0 else -distance,0),(0,distance if y>0 else -distance)])\n        return " ".join(map(str,points[0]+points[1]))+"\\n"\n    if pid=="727A":\n        require(len(v)==2)\n        a,b = v\n        within(a,1,10**9-1)\n        within(b,a+1,10**9)\n        sequence,current = [b],b\n        while current>a:\n            if current%2==0:\n                current //= 2\n            elif current%10==1:\n                current //= 10\n            else:\n                return "NO\\n"\n            sequence.append(current)\n        return "NO\\n" if current!=a else "YES\\n"+str(len(sequence))+"\\n"+" ".join(map(str,sequence[::-1]))+"\\n"\n    if pid=="14B":\n        n,x = v[:2]\n        within(n,1,100)\n        within(x,0,1000)\n        require(len(v)==2+2*n)\n        low,high = 0,1000\n        for i in range(n):\n            a,b = v[2+i*2:4+i*2]\n            within(a,0,1000)\n            within(b,0,1000)\n            require(a!=b)\n            low,high = max(low,min(a,b)),min(high,max(a,b))\n        return str(-1 if low>high else max(0,low-x,x-high))+"\\n"\n    if pid=="106B":\n        n = v[0]\n        within(n,1,100)\n        require(len(v)==1+4*n)\n        laptops = [v[1+i*4:5+i*4] for i in range(n)]\n        for s,r,h,c in laptops:\n            within(s,1000,4200)\n            within(r,256,4096)\n            within(h,1,500)\n            within(c,100,1000)\n        require(len({row[3] for row in laptops})==n)\n        eligible = [i for i,a in enumerate(laptops) if not any(all(b[k]>a[k] for k in range(3)) for b in laptops)]\n        return str(min(eligible,key=lambda i:laptops[i][3])+1)+"\\n"\n    if pid=="182B":\n        d,n = v[:2]\n        within(d,1,10**6)\n        within(n,1,2000)\n        a = array(v[2:],n,1,d)\n        return str(sum(d-x for x in a[:-1]))+"\\n"\n    if pid=="637A":\n        n = v[0]\n        within(n,1,1000)\n        a = array(v[1:],n,1,10**6)\n        final = Counter(a)\n        maximum = max(final.values())\n        running = Counter()\n        for x in a:\n            running[x] += 1\n            if running[x]==maximum:\n                return str(x)+"\\n"\n    if pid=="670B":\n        n,k = v[:2]\n        within(n,1,10**5)\n        within(k,1,min(2*10**9,n*(n+1)//2))\n        a = array(v[2:],n,1,10**9)\n        require(len(set(a))==n)\n        row = (math.isqrt(8*k+1)-1)//2\n        if row*(row+1)//2<k:\n            row += 1\n        index = k-row*(row-1)//2-1\n        return str(a[index])+"\\n"\n    raise ValueError("unknown replenishment recipe")\n\n\ndef string_output(pid,w):\n    if pid=="757A":\n        require(len(w)==1)\n        counts = Counter(token(w[0],r"[a-zA-Z]+",1,10**5))\n        return str(min(counts[c]//n for c,n in Counter("Bulbasaur").items()))+"\\n"\n    if pid=="844A":\n        require(len(w)==2)\n        s = token(w[0],r"[a-z]+",1,1000)\n        k = int(w[1])\n        within(k,1,26)\n        return "impossible\\n" if len(s)<k else str(max(0,k-len(set(s))))+"\\n"\n    n = int(w[0])\n    if pid in ("43A","56A"):\n        within(n,1,100)\n        require(len(w)==n+1)\n        if pid=="43A":\n            counts = Counter(token(s,r"[A-Z]+",1,10) for s in w[1:])\n            require(len(counts)<=2 and sum(c==max(counts.values()) for c in counts.values())==1)\n            return max(counts,key=counts.get)+"\\n"\n        checks = 0\n        for s in w[1:]:\n            if s.isascii() and s.isdigit():\n                within(int(s),0,1000)\n                checks += int(s)<18\n            else:\n                token(s,r"[A-Z]+",1,100)\n                checks += s in DRINKS\n        return str(checks)+"\\n"\n    if pid=="74A":\n        within(n,1,50)\n        require(len(w)==1+8*n)\n        scores = {}\n        for i in range(n):\n            name,*nums = w[1+i*8:9+i*8]\n            token(name,r"[a-zA-Z0-9_]+",1,20)\n            require(name not in scores)\n            plus,minus,*tasks = map(int,nums)\n            within(plus,0,50)\n            within(minus,0,50)\n            for j,x in enumerate(tasks,1):\n                require(x==0 or 150*j<=x<=500*j)\n            scores[name] = sum(tasks)+100*plus-50*minus\n        best = max(scores.values())\n        require(sum(x==best for x in scores.values())==1)\n        return max(scores,key=scores.get)+"\\n"\n    within(n,1,10**5 if pid=="672B" else 2*10**5)\n    require(len(w)==n+2 if pid=="699A" else len(w)==2)\n    s = token(w[1],r"[a-z]+" if pid=="672B" else r"[LR]+" if pid=="699A" else r"[<>]+",n,n)\n    if pid=="672B":\n        return str(-1 if n>26 else n-len(set(s)))+"\\n"\n    if pid=="725A":\n        return str(len(s)-len(s.lstrip("<"))+len(s)-len(s.rstrip(">")))+"\\n"\n    x = array(integers(" ".join(w[2:])),n,0,10**9)\n    require(x==sorted(set(x)) and all(v%2==0 for v in x))\n    times = [(x[i+1]-x[i])//2 for i in range(n-1) if s[i:i+2]=="RL"]\n    return str(min(times) if times else -1)+"\\n"\n\n\ndef make_input(pid,rng,mode):\n    maximum = mode<0\n    if pid=="336A":\n        return lines((rng.choice([-1,1])*(10**9 if maximum else rng.randint(1,100)),rng.choice([-1,1])*(10**9 if maximum else rng.randint(1,100))))\n    if pid=="727A":\n        a = 1 if maximum else rng.randint(1,10**5)\n        b = 10**9 if maximum else rng.randint(a+1,10**9)\n        if mode%2==0:\n            b = a\n            for _ in range(rng.randint(1,8)):\n                new = b*2 if rng.randrange(2) else b*10+1\n                if new>10**9:\n                    break\n                b = new\n        return lines((a,max(a+1,b)))\n    if pid=="14B":\n        n = 100 if maximum else rng.randint(1,15)\n        x = rng.randint(0,1000)\n        records = [rng.sample(range(1001),2) for _ in range(n)]\n        if mode==-1:\n            records = [(0,1000)]*n\n        if mode==-2:\n            records = [(0,1),(999,1000)]+[(0,1000)]*(n-2)\n        return lines((n,x),*records)\n    if pid=="43A":\n        n = 100 if maximum else rng.choice(range(1,20,2))\n        a,b = rng.sample(["ALPHA","BETA","C","DDDDDDDDDD","OTHER"],2)\n        goals = [rng.choice((a,b)) for _ in range(n)]\n        if goals.count(a)==goals.count(b):\n            goals[-1] = b if goals[-1]==a else a\n        return lines(n,*goals)\n    if pid=="56A":\n        n = 100 if maximum else rng.randint(1,20)\n        people = [rng.choice(DRINKS+[str(rng.randint(0,1000)),"WATER","TEA","BEERBEER","B"*100,"17","18"]) for _ in range(n)]\n        return lines(n,*people)\n    if pid=="74A":\n        n = 50 if maximum else rng.randint(1,12)\n        while True:\n            records = [[f"person_{i}",rng.randint(0,50),rng.randint(0,50)]+[rng.choice([0,rng.randint(150*j,500*j)]) for j in range(1,6)] for i in range(n)]\n            s = lines(n,*records)\n            try:\n                output(pid,s)\n                return s\n            except ValueError:\n                pass\n    if pid=="106B":\n        n = 100 if maximum else rng.randint(1,15)\n        prices = rng.sample(range(100,1001),n)\n        return lines(n,*[(rng.randint(1000,4200),rng.randint(256,4096),rng.randint(1,500),p) for p in prices])\n    if pid=="182B":\n        d,n = (10**6,2000) if maximum else (rng.randint(1,100),rng.randint(1,20))\n        return lines(d,n,values(n,1,d,mode,rng))\n    if pid=="637A":\n        n = 1000 if maximum else rng.randint(1,20)\n        return lines(n,values(n,1,10**6 if maximum else 5,mode,rng))\n    if pid=="670B":\n        n = 10**5 if maximum else rng.randint(1,25)\n        k = 2*10**9 if maximum else rng.randint(1,n*(n+1)//2)\n        ids = list(range(10**9-n+1,10**9+1)) if maximum else rng.sample(range(1,10001),n)\n        return lines((n,k),ids)\n    if pid in ("672B","699A","725A"):\n        n = (10**5 if pid=="672B" else 2*10**5) if maximum else rng.randint(1,35)\n        alphabet = "abcdefghijklmnopqrstuvwxyz" if pid=="672B" else "LR" if pid=="699A" else "<>"\n        s = alphabet[0]*n if mode==-1 else alphabet[-1]*n if mode==-2 else "".join(rng.choice(alphabet) for _ in range(n))\n        if pid=="699A":\n            coords = [2*i for i in range(n)] if maximum else sorted(rng.sample(range(0,500000001),n))\n            if not maximum:\n                coords = [2*i for i in coords]\n            return lines(n,s,coords)\n        return lines(n,s)\n    if pid=="757A":\n        n = 10**5 if maximum else rng.randint(1,100)\n        s = "B"*n if mode==-1 else ("Bulbasaur"*((n+8)//9))[:n] if mode==-2 else "".join(rng.choice("BulbasaurABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz") for _ in range(n))\n        return lines(s)\n    if pid=="844A":\n        n = 1000 if maximum else rng.randint(1,35)\n        s = "a"*n if mode==-1 else "".join(rng.choice("abcdefghijklmnopqrstuvwxyz") for _ in range(n))\n        return lines(s,26 if maximum else rng.randint(1,26))\n    raise ValueError("unimplemented replenishment input")\n\n\ndef extras(pid):\n    rng = random.Random("1000-replenish-v1-"+pid)\n    seen,result = set(),[]\n    for mode in [-1,-2,-3]+list(range(180)):\n        s = make_input(pid,rng,mode)\n        if s in seen:\n            continue\n        seen.add(s)\n        result.append({"input":s,"output":output(pid,s),"caseKind":"max-size" if mode<0 else "boundary-adversarial"})\n    return result\n'}
